        Verse(book = "1 Kwonik", chapter = 2, verseNumber = 3, text = "Jida te gen senk pitit gason antou. Chwa, moun peyi Kanaran, te fè twa pitit pou li. Se te Er, Onan ak Chela. Er, pi gran pitit gason Jida a, te sitèlman fè sa ki mal, Seyè a touye l'.", bookId = 13),
