        Verse(book = "1 Kwonik", chapter = 2, verseNumber = 45, text = "Chamayi te papa Maon ki te papa Betsou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 2, verseNumber = 46, text = "Kalèb te gen yon lòt fanm kay yo te rele Efa. Li fè twa lòt pitit avè l': Aran, Moza ak Gazèz. Aran te gen yon pitit gason yo te rele Gazèz tou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 2, verseNumber = 47, text = "Yon nonm yo te rele Jadayi te gen sis pitit gason: Regèm, Jotam, Gechan, Pelèt, Efa ak Chaf.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 2, verseNumber = 48, text = "Kalèb te gen yon lòt fanm kay ankò ki te rele Maka. Maka fè de pitit gason pou li: Chebè ak Tirana.", bookId = 13),
