        Verse(book = "1 Kwonik", chapter = 2, verseNumber = 50, text = "Tout moun sa yo te nan fanmi Kalèb. Our te premye pitit gason Efrata ak Kalèb. Men pitit li yo: Chobal ki te papa Kiriyat-Jearim,", bookId = 13),
