        Verse(book = "1 Kwonik", chapter = 2, verseNumber = 53, text = "ak moun ki te rete nan Kiriyat-Jearim, ki vle di: moun Jetè yo, moun Pout yo, moun Choumat yo ak moun Michra yo. Moun ki rete lavil Sora ak lavil Echtawòl yo te soti nan branch fanmi moun sa yo tou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 2, verseNumber = 54, text = "Salma, papa Betleyèm, te zansèt moun lavil Netofat, moun lavil Atwòt-Bèt-Joab, ak moun Sora yo ki te yonn nan de branch fanmi ki te rete Manarat yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 2, verseNumber = 55, text = "Men branch fanmi moun ki te abil nan ekri ak kopye dokiman. Yo te rete lavil Jabèz. Se te moun Tira yo, moun Chima yo ak moun Souka yo. Se moun branch fanmi Kayen ki soti nan fanmi Amat, zansèt moun Rekab yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 1, text = "Men non pitit gason David vin genyen antan li te lavil Ebwon. Pi gran an te rele Amon. Se Akinoam, moun lavil Jizreyèl, ki te manman l'. Dezyèm lan te rele Danyèl. Se Abigayil, moun lavil Kamèl, ki te manman l'.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 2, text = "Twazyèm lan te rele Absalon. Se Maka, pitit fi Talmayi, wa lavil Gechou a, ki te manman l'. Katriyèm lan te rele Adonija. Se Agit ki te manman l'.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 3, text = "Senkyèm lan te rele Chefatya. Se Abital ki te manman l'. Sizyèm lan te rele Jitreyam. Se Egla, madan David, ki te manman l'.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 4, text = "Sis pitit sa yo te fèt lavil Ebwon kote David te gouvènen pandan sètan sis mwa. Apre sa, David al rete lavil Jerizalèm kote li gouvènen pandan tranntwazan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 5, text = "Li fè anpil pitit gason la tou. Batcheba, pitit fi Amiyel la, fe kat pitit gason pou li: Chimea, Chabab, Natan ak Salomon.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 6, text = "Li te gen nèf lòt pitit gason: Iba, Elichwa, Elpelèt,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 7, text = "Noga, Nefèg, Jafya,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 8, text = "Elichama, Elyada, Elifelèt.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 9, text = "David te fè lòt pitit gason toujou ak lòt fanm kay mete sou sa yo. Li te gen yon pitit fi yo te rele Tama.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 10, text = "Salomon te papa Woboram, Woboram te papa Abija, Abija te papa Asa, Asa te papa Jozafa,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 11, text = "Jozafa te papa Joram, Joram te papa Okozyas, Okozyas te papa Joas,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 12, text = "Joas te papa Amazya, Amazya te papa Azarya, Azarya te papa Jotam,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 13, text = "Jotam te papa Akaz, Akaz te papa Ezekyas, Ezekyas te papa Manase,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 14, text = "Manase te papa Amon, Amon te papa Jozyas.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 15, text = "Jozyas te gen kat pitit gason. Pi gran an te rele Jokanan, dezyèm lan Jojakim, twazyèm lan Sedesyas, katriyèm lan Chaloum.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 16, text = "Jojakim te papa Jekonya ak Sedesyas.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 17, text = "Men non fanmi wa Jojakim moun Babilòn yo te fè prizonye a. Jojakim te gen sèt pitit gason: Chealtyèl,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 18, text = "Malkiram, Pedaja, Chenasa, Jekamya, Ochama ak Nedabya.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 19, text = "Pedaja te gen de pitit gason: Zowobabèl ak Chimeyi. Zowobabel te gen de pitit gason: Mechoulam ak Ananya, ak yon pitit fi, Chelomit.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 20, text = "Li te fè senk lòt pitit gason. Se te Achouba, Ojèl, Berekya, Asadya ak Jouchabesèd.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 21, text = "Ananya te gen de pitit gason: Pelatya ak Jechaya. Jechaya te papa Refaya, Refaya te papa Anan, Anan te papa Obadya, Obadya te papa Chekanya.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 22, text = "Chekanya te gen yon pitit gason, Chemaya, ak senk pitit pitit: Atouch, Igal, Barya, Nearya ak Chafat.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 23, text = "Nearya te gen twa pitit gason: Elioenayi, Izkiya ak Azrikam.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 3, verseNumber = 24, text = "Elioenayi te gen sèt pitit gason: Odavya, Elyachib, Pelaya, Akoub, Joanan, Delaya ak Anani.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 1, text = "Men non lòt pitit gason Jida te gen: Perèz, Ezwon, Kami, Our ak Chobal.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 2, text = "Chobal te papa Reaja, Reaja te papa Jakat, Jakat te papa Akoumayi ak Laad. Se yo ki zansèt moun ki rete lavil Zora.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 3, text = "Etam te pitit Our. Se li ki papa Jizreyèl, Ichma, Idbak ak yon pitit fi yo rele Azelèl-poni.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 4, text = "Penwèl, yon lòt pitit Our, te papa Gedò. Ezè, yon lòt pitit Our, te papa Oucha. Our te premye pitit Efrata, madan Kalèb. Se branch fanmi l' lan ki te bati lavil Betleyèm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 5, text = "Achou, ki te bati lavil Tekoa, te gen de madanm: Ela ak Nara.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 6, text = "Nara te fè kat pitit gason pou li. Se te Aouzam, Efè, Temeni ak Ayachtari.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 7, text = "Ela te fè twa pitit gason pou li: Zerèt, Soa ak Etnan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 8, text = "Kòz te papa Anoub ak Zobeba. Se li ki zansèt tout branch fanmi Arèl, pitit gason Awoum.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 9, text = "Te gen yon moun yo te rele Jabez. Nan tout fanmi l', se li menm yo te pi respekte. Manman l' te rele l' konsa, paske li te soufri anpil lè li t'ap fè l'.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 10, text = "Men Jabèz te lapriyè Bondye pèp Izrayèl la, li te di l': -Tanpri, Bondye, beni mwen. Ban m' anpil tè. Kanpe la ave m'. Pa kite ankenn malè rive m' pou m' pa soufri. Se konsa Bondye ba li sa l' te mande a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 11, text = "Keloub, frè Choula, te gen yon pitit gason yo te rele Meyi. Meyi te papa Echton.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 12, text = "Echton te papa Betrafa, Pasea ak Techima. Se Techima ki te tabli lavil Nagach. Se fanmi moun sa yo ki rete lavil Reka.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 13, text = "Kenaz te gen de pitit gason: Otnyèl ak Seraja. Otnyèl te gen de pitit gason tou: Atat ak Meonotayi.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 14, text = "Meonotayi te papa Ofra. Seraja te papa Joab, zansèt moun ki rete nan fon Bòs Atizan yo. Tout moun sa yo te bòs nan metye yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 15, text = "Kalèb, pitit gason Jefoune, te gen twa pitit gason pou tèt pa l': Iwou, Ela ak Nam. Ela te papa Kenaz.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 16, text = "Jealelèl te gen kat pitit gason: Zif, Zifa, Tirya ak Azareyèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 17, text = "-", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 18, text = "Esdras te gen kat pitit gason: Jetè, Merèd, Efè ak Jalou. Merèd marye ak Bitya, yonn nan pitit fi farawon peyi Lejip la. Yo fè yon pitit fi, Miryam, ak de pitit gason: Chamayi ak Ichba. Ichba te papa Estemoa. Merèd te pran yon fanm nan branch fanmi Jida a tou pou madanm. Madanm sa a ba li twa pitit gason: Jerèd, papa Gedò, Ebè, papa Soko, ak Jekoutiyèl, papa Zanoa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 19, text = "Odija marye ak sè Naam lan. Se pitit yo ki zansèt branch fanmi moun Gram yo ki te rete lavil Kejila, ak branch fanmi moun Makat yo ki te rete lavil Estemoa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 20, text = "Chimon te gen kat pitit gason: Amnon, Rina, Bennanan ak Tilon. Icheyi te gen de pitit gason: Zoet ak Bennzoèt.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 21, text = "Men moun ki nan branch fanmi Chela, pitit Jida a: Er, papa Leka, Lada, papa Marecha, branch fanmi moun ki fè bon twal fin nan lavil Bètachbea yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 22, text = "Jokim, moun ki rete lavil Kozeba, Joas ak Saraf. Moun sa yo te marye ak fanm moun peyi Moab, lèfini yo tounen vin rete lavil Betleyèm, dapre sa moun lontan yo ap repete.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 23, text = "Se moun ki te konn fè veso an tè. Yo te rete lavil Netayim ak lavil Gedera. Se yo ki te konn travay pou wa a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 24, text = "Simeyon te gen senk pitit gason: Nemwèl, Jamen, Jarib, Zera ak Sayil.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 25, text = "Sayil te papa Chaloum, Chaloum te papa Mibsam, Mibsam te papa Michma,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 26, text = "Michma te papa Amwèl, Amwèl te papa Zakou, Zakou te papa Chimeyi.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 27, text = "Chimeyi te gen sèz pitit gason ak sis pitit fi. Men lòt frè l' yo pa t' fè anpil pitit. Se konsa branch fanmi Simeyon an pa t' rive gen menm kantite moun ak branch fanmi Jida a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 28, text = "Rive sou rèy wa David, moun branch fanmi Simeyon yo te rete nan lavil sa yo: Becheba, Molada, Azachwal,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 29, text = "Bila, Ezèm, Tolad,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 30, text = "Betwèl, Oma, Zikla,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 31, text = "Bètmakabòt, Azasousim, Bètbireyi ak Charayim.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 32, text = "Yo te rete nan senk lòt kote apre sa: Etam, Ayin, Rimon, Tochenn ak Achan,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 33, text = "ak tout ti bouk ki nan vwazinaj yo, rive lavil Balat, nan direksyon sid. Tou sa se kote yo t'ap viv ak liv rejis fanmi yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 34, text = "-", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 35, text = "Men moun ki te chèf branch fanmi Simeyon yo: Mechobab, Jamlèk, Jocha, pitit gason Amazya, ak Joèl, Jeou, pitit gason Jozibyas ki te pitit Seraja, pitit pitit Asiyèl,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 36, text = "Elioenayi, Jakoba, Jekoaja, Asaya, Adyèl, Jezimyèl, Benaja,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 37, text = "Ziza, pitit gason Chifi, ki te pitit gason Alon. Alon sa a te pitit Jedaja. Jedaja menm te pitit Chimri ki te pitit Chemaja.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 38, text = "Tout moun nou sot nonmen la yo te chèf nan fanmi yo. Branch fanmi an t'ap peple toujou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 39, text = "Y' al chache patiraj pou mouton yo toupre lavil Gedò, sou bò solèy leve nan fon kote lavil la ye a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 40, text = "La, yo jwenn yon bon patiraj ki te fre nan yon plenn kote ki pa t' gen bri ni dezòd. Se la moun branch fanmi Kam yo te rete nan tan lontan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 41, text = "Sou rèy Ezekyas, wa peyi Jida, moun nou sot bay non yo la a rive lavil Gedò, yo touye moun fanmi Kam yo nèt tankou yon ofrann pou Bondye. Yo detwi tout lavil la ak ti joupa moun yo. Yo pran plas moun yo nan peyi a, paske te gen anpil bon patiraj pou mouton ak kabrit yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 42, text = "Senksan (500) lòt moun nan branch fanmi Simeyon an pati pou mòn Seyi, nan peyi Edon. Yo te gen pou chèf kat pitit gason Icheyi yo: Pelatya, Nearya, Refaja ak Ouzyèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 4, verseNumber = 43, text = "Lè yo rive, yo touye rès moun Amalèk yo. Depi lè sa a se la yo rete jouk jounen jòdi a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 1, text = "Men moun branch fanmi Woubenn, premye pitit Izrayèl la. Se Woubenn ki te premye pitit gason, men li te pèdi dwa premye pitit li paske li te kouche ak yonn nan madanm papa l' yo. Se pitit Jozèf yo, yon lòt pitit Izrayèl, yo te bay dwa premye pitit la. Tansèlman, yo pa t' pote non Jozèf la sou rejis tankou premye pitit.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 2, text = "Lèfini, se branch fanmi Jida a ki te vin pi fò. Se li menm ki bay yon chèf pou gouvènen tout branch fanmi yo. Men tout jan, se Jozèf yo te bay dwa premye pitit la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 3, text = "Woubenn, pi gran nan pitit gason Izrayèl yo, te gen kat pitit gason: Enòk, Palou, Ezwon ak Kami.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 4, text = "Joèl te papa Chemaja, Chemaja te papa Gòg, Gòg te papa Chimeyi,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 5, text = "Chimeyi te papa Mika, Mika te papa Reaja, Reaja te papa Baal.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 6, text = "Baal te papa Bera, yonn nan chèf fanmi Woubenn yo. Se li menm Tiglat-Pilesè, wa peyi Lasiri a, te depòte.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 7, text = "Men lis lòt chèf fanmi Woubenn yo dapre rejis kote yo te ekri non yo. N'ap konmanse ak pi ansyen an. Te gen Jeyèl, Zakari,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 8, text = "Bela, pitit Aza, pitit pitit Chema nan branch fanmi Joèl. Se yo ki te rete nan zòn Awoyè, rive Nebo ak Baal Meon sou nan nò.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 9, text = "Yo te gen anpil mouton ak kabrit nan tout peyi Galarad la. Se konsa yo pran tout peyi a depi bò dezè a rive jouk bò larivyè Lefrat bò solèy leve.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 10, text = "Sou rèy wa Sayil, moun Woubenn yo atake moun Aga yo. Yo bat yo, yo pran tout tè moun yo ki sou bò solèy leve nan peyi Galarad.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 11, text = "Branch fanmi Gad la te rete sou bò nò moun branch fanmi Woubenn yo, nan peyi Bazan, rive Salka sou bò solèy leve.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 12, text = "Joèl te vin an premye. Apre li te gen Chafam, Janayi ak Chafat nan peyi Bazan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 13, text = "Lòt moun nan fanmi an te fè sèt branch. Men non branch fanmi yo, dapre non zansèt yo: Mikayèl, Mechoulam, Cheba, Jorayi, Jakan, Zya ak Ebè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 14, text = "Yo tout te pitit Abikayil ki te pitit Ouri. Ouri te pitit Jawoja ki te pitit Galarad. Galarad te pitit Mikayèl ki te pitit Jechichayi. Jechichayi te pitit Jakdo ki te pitit Bouz.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 15, text = "Aki, pitit Abdyèl, pitit pitit Gouni, te zansèt tout fanmi sa yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 16, text = "Yo te rete nan peyi Bazan ak nan peyi Galarad, nan lavil yo ak nan tout savann patiraj peyi Sawon an.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 17, text = "Se sou rèy Jotam, wa peyi Jida, ak Jewoboram, wa peyi Izrayèl, yo te fè rejis sa yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 18, text = "Branch fanmi Woubenn lan, branch fanmi Gad la ak mwatye branch fanmi Manase a te gen antou karannkatmil sètsanswasant (44.760) sòlda, tout vanyan gason, ki konn sèvi ak pwotèj an fè ak nepe, ak banza. Yo te abil nan fè lagè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 19, text = "Yo fè lagè ak moun Aga yo ki te rete lavil Jetou, lavil Nafich ak lavil Nodab.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 20, text = "Yo pa t' pou kont yo nan batay la. Yo te mete konfyans yo nan Bondye. Pandan batay la, yo lapriyè mande l' konkou. Bondye reponn yo, li lage tout moun Aga yo ansanm ak tout moun ki te avèk moun Aga yo nan men yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 21, text = "Yo pran senkantmil (50.000) chamo, desansenkantmil (250.000) mouton ak kabrit, demil (2.000) bourik nan men lènmi yo. Yo fè sanmil (100.000) prizonye.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 22, text = "Yo touye anpil ladan lènmi yo paske batay la se Bondye menm ki t'ap mennen l' pou yo. Se konsa yo rete nan zòn sa a jouk jou yo depòte yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 23, text = "Moun mwatye branch fanmi Manase ki sou bò solèy leve larivyè Jouden an te rete nan zòn ki soti Bazan moute nan nò rive Baalèmòn, lavil Sini ak mòn Emon. Yo te peple anpil.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 24, text = "Men non chèf fanmi yo: Efè, Icheyi, Eliyèl, Azryèl, Jeremi, Odavya ak Jadyèl. Mesye sa yo te vanyan sòlda, chèf fanmi yo. Tout moun t'ap nonmen non yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 25, text = "Men, pèp la te vire do bay Bondye zansèt yo a, y' al kouri fè sèvis pou bondye lòt nasyon Bondye te disparèt pou fè plas pou yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 5, verseNumber = 26, text = "Se poutèt sa, Bondye pèp Izrayèl la fè Poul, wa peyi Lasiri a ki te rele Tiglat-Pilesè tou, anvayi peyi yo a, depòte moun branch fanmi Woubenn yo, moun branch fanmi Gad yo ak moun mwatye branch fanmi Manase yo. Li mennen yo lavil Ala, lavil Abò, lavil Ara ak bò larivyè Gozan kote yo rete jouk jounen jòdi a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 1, text = "Levi te gen twa pitit gason: Gèchon, Keyat ak Merari.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 2, text = "Keyat te gen kat pitit gason: Amram, Jizeya, Ebwon ak Ouzyèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 3, text = "Amram te gen de pitit gason, Arawon ak Moyiz ak yon pitit fi yo te rele Miryam. Arawon te gen kat pitit gason: Nadab, Abiyou, Eleaza ak Itama.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 4, text = "Eleaza te papa Fineas, Fineas te papa Abichwa,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 5, text = "Abichwa te papa Bouki, Bouki te papa Ouzi,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 6, text = "Ouzi te papa Zeraja, Zeraja te papa Merajòt,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 7, text = "Merajòt te papa Amarya, Amarya te papa Akitoub,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 8, text = "Akitoub te papa Zadòk, Zadòk te papa Akimaz,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 9, text = "Akimaz te papa Azarya, Azarya te papa Joanan,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 10, text = "Joanan te papa Azarya. Se li menm Azarya ki te sèvi prèt nan tanp Salomon te bati lavil Jerizalèm lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 11, text = "Azarya te papa Amarya, Amarya te papa Achitoub,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 12, text = "Achitoub te papa Zadòk, Zadòk te papa Chaloum,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 13, text = "Chaloum te papa Ilkija, Ilkija te papa Azarya,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 14, text = "Azarya te papa Seraja, Seraja te papa Jeosadak.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 15, text = "Wa Nèbikadneza te depòte Jeosadak ansanm ak tout moun peyi Jida ak tout moun lavil Jerizalèm yo, jan Bondye te vle l' la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 16, text = "Levi te gen twa pitit gason: Gèchon, Keyat ak Merari.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 17, text = "Men non pitit Gechon yo: Libni ak Chimeyi.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 18, text = "Keyat te papa Amram, Jizeya, Ebwon ak Ouzyèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 19, text = "Merari te papa Makli ak Mouchi. Men non branch fanmi Levi yo dapre zansèt yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 20, text = "Gèchon te papa Libni, Libni te papa Jakat, Jakat te papa Zima,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 21, text = "Zima te papa Joak, Joak te papa Ido, Ido te papa Zerak, Zerak te papa Jeatrayi.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 22, text = "Keyat te papa Aminadab, Aminadab te papa Kore, Kore te papa Asi.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 23, text = "Asi te papa Elkana, Elkana te papa Ebyasaf, Ebyasaf te papa Asi.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 24, text = "Asi te papa Tajat, Tajat te papa Ouryèl, Ouryèl te papa Ouzya, Ouzya te papa Sayil.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 25, text = "Elkana te gen de pitit gason: Amasayi ak Akimòt.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 26, text = "Akimòt te papa Elkana, Elkana te papa Zofayi, Zofayi te papa Naat,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 27, text = "Naat te papa Eliyab, Eliyab te papa Jeworam, Jeworam te papa Elkana. Elkana te papa Samyèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 28, text = "Samyèl te gen de pitit gason: Joèl, pi gran an ak Abija, dezyèm lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 29, text = "Merari bò pa l' te papa Makli, Makli te papa Libni, Libni te papa Chimeyi, Chimeyi te papa Ouza.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 30, text = "Ouza te papa Chimeya, Chimeya te papa Agija, Agija te papa Asaja.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 31, text = "Men moun David te mete pou reskonsab tout chante nan Tanp Seyè a lè y'a fin enstale Bwat Kontra a ladan l'.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 32, text = "Se yo ki te konn chante devan Tant Randevou a, jouk wa Salomon te fin bati Tanp Seyè a lavil Jerizalèm. Yo te fè travay yo yonn apre lòt dapre regleman yo te ba yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 33, text = "Men non sanba yo ak tout fanmi yo: Nan fanmi Keyat la te gen Eyman premye sanba, ki te pitit Joèl, ki li menm te pitit Samyèl,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 34, text = "ki li menm te pitit Elkana, ki li menm te pitit Jeworam, ki li menm te pitit Eliyèl, ki li menm te pitit Toak,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 35, text = "ki li menm te pitit Zouf, ki li menm te pitit Elkana, ki li menm te pitit Maat, ki li menm te pitit Amasayi,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 36, text = "ki li menm te pitit Elkana, ki li menm te pitit Joèl, ki li menm te pitit Azarya, ki li menm te pitit Sofoni,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 37, text = "ki li menm te pitit Tat, ki li menm te pitit Asi, ki li menm te pitit Ebyasaf, ki li menm te pitit Kore,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 38, text = "ki li menm te pitit Jizeya, ki li menm te pitit Keyat, ki li menm te pitit Levi, ki li menm te pitit Izrayèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 39, text = "Asaf, dezyèm sanba a, te kanpe sou bò dwat Eyman. Asaf te pitit Berekya, ki li menm te pitit Chimeya,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 40, text = "ki li menm te pitit Mikayèl, ki li menm te pitit Baseja, ki li menm te pitit Malkija,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 41, text = "ki li menm te pitit Etni, ki li menm te pitit Zerak, ki li menm te pitit Adaja.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 42, text = "ki li menm te pitit Etan, ki li menm te pitit Zima, ki li menm te pitit Chimeyi,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 43, text = "ki li menm te pitit Jakat, ki li menm te pitit Gèchon, ki li menm te pitit Levi.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 44, text = "Etan ki soti nan branch fanmi Merari a te twazyèm sanba a ki te sou bò gòch Eyman. Se pitit Kichi li te ye. Kichi sa a te pitit Abdi, ki li menm te pitit Malouk,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 45, text = "ki li menm te pitit Asabija, ki limenm te pitit Amazya, ki li menm te pitit Ilkija,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 46, text = "ki li menm te pitit Amasi, ki li menm te pitit Bani, ki li menm te pitit Chemè,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 47, text = "ki li menm te pitit Mali, ki li menm te pitit Mouchi, ki li menm te pitit Merari, ki li menm te pitit Levi.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 48, text = "Lòt moun branch fanmi Levi yo te gen travay pa yo nan sèvis Tanp Seyè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 49, text = "Se Arawon ak pitit li yo ki te pou boule bèt yo te ofri sou lotèl yo te mete la pou sa, ak lansan sou lotèl lansan an. Se yo menm tou ki te reskonsab pou tout sèvis nan kay yo mete apa nèt pou Seyè a, pou mande padon pou peche pèp Izrayèl la, dapre tout regleman Moyiz, sèvitè Bondye a, te bay.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 50, text = "Men fanmi Arawon yo: Arawon te papa Eleaza, Eleaza te papa Fineas, Fineas te papa Abichwa,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 51, text = "Abichwa te papa Bouki, Bouki te papa Ouzi, Ouzi te papa Zeraja,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 52, text = "Zeraja te papa Merajòt, Merajòt te papa Amarya, Amarya te papa Akitoub,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 53, text = "Akitoub te papa Zadòk, Zadòk te papa Akimaz.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 54, text = "Men kote fanmi Arawon yo te rete ak limit zòn ki te pou yo. Lè yo fè tiraj osò, se branch fanmi Keyat yo ki soti an premye avèk", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 55, text = "Ebwon, nan pòsyon tè ki pou branch fanmi Jida a, ansanm ak tout savann pou bèt yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 56, text = "Yo bay Kalèb, pitit Jefoune a, tout jaden ki te andeyò lavil la ak tout ti bouk ki te sou lòd li yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 57, text = "Men lavil yo te bay moun branch fanmi Arawon yo: Ebwon ansanm ak tout savann pou bèt yo, Libna ak tout savann pou bèt yo, Jati ak tout savann pou bèt yo, Estemoa ak tout savann pou bèt yo,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 58, text = "Ilenn ak tout savann pou bèt yo, Debi ak tout savann pou bèt yo,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 59, text = "Achan ak tout savann pou bèt yo, Bètchemèch ak tout savann pou bèt yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 60, text = "Nan pòsyon tè moun branch fanmi Benjamen yo, yo ba yo Geba ak tout savann pou bèt yo, Alemèt ak tout savann pou bèt yo, Anatòt ak tout savann pou bèt yo. Sa te fè antou trèz lavil pou yo te separe bay chak fanmi pa yo apa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 61, text = "Yo pran dis lavil nan pòsyon tè ki pou branch fanmi Efrayim, pou branch fanmi Dann lan ak pou lòt mwatye branch fanmi Manase a, yo bay rès moun nan fanmi Keyat la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 62, text = "Trèz lavil nan pòsyon tè ki pou branch fanmi Isaka, branch fanmi Asè, branch fanmi Nèftali ak lòt mwatye branch fanmi Manase nan peyi Bazan an te soti pou branch fanmi Gèchon yo, chak fanmi ak lavil pa yo apa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 63, text = "Konsa tou, douz lavil nan pòsyon tè ki pou branch fanmi Woubenn, branch fanmi Gad ak branch fanmi Zabilon soti pou branch fanmi Merari yo, chak fanmi ak lavil pa yo apa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 64, text = "Se konsa moun pèp Izrayèl yo bay moun Levi yo lavil sa yo pou yo rete ansanm ak tout savann pou bèt yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 65, text = "Yo te tire osò tou pou yo ba yo lavil nan pòsyon tè branch fanmi Jida, branch fanmi Simeyon ak branch fanmi Benjamen, jan nou sot nonmen yo a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 66, text = "Gen kèk fanmi nan branch Keyat la ki te jwenn lavil nan pòsyon tè ki pou branch fanmi Efrayim lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 67, text = "Yo ba yo tou lavil Sichèm, yonn nan lavil kote moun ki touye moun ka kouri al chache pwoteksyon an, ansanm ak tout savann pou bèt yo nan mòn Efrayim lan, Gezè ansanm ak tout savann pou bèt yo,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 68, text = "Yokmeam ak tout savann pou bèt yo, Bètowon ak tout savann pou bèt yo,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 69, text = "Ajalon ak tout savann pou bèt yo,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 70, text = "Gat-Rimon ak tout savann pou bèt yo. Nan pòsyon tè ki pou lòt mwatye branch fanmi Manase a, sou bò solèy kouche, yo ba yo Tanak ak tout savann pou bèt yo, Jibleam ak tout savann pou bèt yo. Tou sa pou rès fanmi nan branch Keyat la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 71, text = "Nan pòsyon tè ki pou mwatye branch fanmi Manase a sou bò solèy leve, yo bay moun fanmi Gèchon yo lavil Golan nan peyi Bazan ak tout savann pou bèt yo, lavil Astawòt ak tout savann pou bèt yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 72, text = "Nan pòsyon tè ki pou branch fanmi Isaka a, yo ba yo Kadès ak tout savann pou bèt yo, Dobera ak tout savann pou bèt yo,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 73, text = "Ramòt ak tout savann pou bèt yo, Anèm ak tout savann pou bèt yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 74, text = "Nan pòsyon tè ki pou branch fanmi Asè a, yo ba yo Machal ak tout savann pou bèt yo, Abdon ak tout savann pou bèt yo,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 75, text = "Oukòk ak tout savann pou bèt yo, Reyòb ak tout savann pou bèt yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 76, text = "Nan pòsyon tè pou branch fanmi Neftali a, yo ba yo Kadès nan peyi Galile ak tout savann pou bèt yo, Amon ak tout savann pou bèt yo, Kiriyatayim ak tout savann pou bèt yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 77, text = "Nan pòsyon tè ki pou branch fanmi Zabilon an, yo bay Rimono ak tout savann pou bèt yo, Tabò ak tout savann pou bèt yo pou rès moun nan branch fanmi Merari a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 78, text = "Nan pòsyon tè ki pou branch fanmi Woubenn lan, sou bò solèy leve larivyè Jouden, anfas lavil Jeriko, yo ba yo Bezè nan dezè a ak tout savann pou bèt yo, Jaza ak tout savann pou bèt yo,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 79, text = "Kedemòt ak tout savann pou bèt yo, Mefat ak tout savann pou bèt yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 80, text = "Nan pòsyon tè ki pou branch fanmi Gad la, yo ba yo Ramòt nan peyi Galarad ak tout savann pou bèt yo, Manayim ak tout savann pou bèt yo,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 6, verseNumber = 81, text = "Esbon ak tout savann pou bèt yo, Jazè ak tout savann pou bèt yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 1, text = "Isaka te gen kat pitit gason: Tola, Fwa, Yachoub ak Chimwon.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 2, text = "Tola te gen sis pitit gason: Ouzi, Refaja, Jeryèl, Jakmayi, Jibsam ak Samyèl. Se yo ki te chèf fanmi Tola yo. Se te yon bann vanyan sòlda brave danje. Sou rèy David te gen venndemil sisan (22.600) moun nan branch fanmi sa a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 3, text = "Ouzi te gen yon sèl pitit gason: Jizrakya. Jizrakya te gen kat pitit gason: Mikayèl, Obadya, Joèl ak Jichiya. Sa fè antou senk chèf fanmi.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 4, text = "Yo te gen anpil madanm ak anpil pitit gason. Se konsa branch fanmi sa a te bay anpil gason bon pou fè lagè. Antou trannsimil (36.000).", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 5, text = "Lè yo konte tout branch fanmi Isaka a dapre rejis fanmi yo, yo te rive sou katrevensètmil (87.000) gason antou, tout vanyan sòlda.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 6, text = "Benjamen te gen twa pitit gason: Bela, Bekè ak Jedyayèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 7, text = "Bela te gen senk pitit gason: Esbon, Ouzi, Ouzyèl, Jerimòt ak Iri. Yo tout te chèf fanmi yo. Yo te vanyan sòlda. Dapre rejis fanmi yo, yo te rive gen venndemil trannkat (22.034) moun nan fanmi yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 8, text = "Men non pitit gason Bekè yo: Zemira, Joas, Elyezè, Elioenayi, Omri, Jeremòt, Abija, Anatòt ak Alamèt. Yo tout te pitit gason Bekè, chèf fanmi yo, tout vanyan sòlda.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 9, text = "Dapre rejis fanmi yo, te gen venmil desan (20.200) gason antou sou zòd yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 10, text = "Men pitit Jedyayèl la: Bilan. Men pitit Bilan yo: Jeouch, Benjamen, Eyoud, Kenana, Zetan, Tasis ak Akichaka.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 11, text = "Yo tout te moun fanmi Jedyayèl, chèf fanmi yo ak vanyan sòlda. Yo te gen disètmil desan (17.200) gason bon pou fè lagè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 12, text = "Iri te gen de pitit gason: Choupim ak Oupim. Ouchim te pitit Ayè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 13, text = "Men pitit gason Neftali yo: Jazeyèl, Gouni, Jezè ak Chaloum. Yo tout te pitit pitit Bila.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 14, text = "Men pitit gason Manase te fè ak fanm kay peyi Siri a: Asriyèl ak Maki, papa Galarad.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 15, text = "Maki fè afè ak Maka, yon fanm nan fanmi Oupim ak Choupim. Dezyèm pitit gason Maki a te rele Zelofeyad. Zelofeyad te fè pitit fi ase.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 16, text = "Maka, madan Maki, fè yon pitit gason. Li rele l' Perès. Frè Perès la te rele Serès. Serès te gen de pitit gason: Oulam ak Rekèm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 17, text = "Oulam fè yon pitit gason yo te rele Bedan. Yo tout te pitit Galarad, ki te pitit Maki, ki li menm te pitit Manase.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 18, text = "Sè Maki a te rele Amolekèt. Li fè twa pitit gason: Ichòd, Abyezè ak Makla.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 19, text = "Men pitit Chemida yo: se te Akcham, Sichèm, Liki ak Anyam.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 20, text = "Efrayim te papa Soutelak ki te papa Berèd. Berèd te papa Taka ki te papa Elada. Elada te papa Taka", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 21, text = "ki te papa Zabad. Zabad te papa Soutelak. Efrayim te gen de lòt pitit gason: Ezè ak Elad. Men, moun ki rete nan zòn Gad la touye yo paske yo te vin vòlò mouton yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 22, text = "Lè sa a, Efrayim, papa yo, te pran lapenn pou yo pandan lontan. Se fanmi l' yo ki vin ba l' kouraj.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 23, text = "Apre sa, li al kouche ak madanm li. Madanm lan vin ansent, li fè yon pitit gason, li rele l' Berya paske malè te tonbe sou kay la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 24, text = "Chera, pitit fi Berya a, bati Bètowon anba ak Bètowon anwo. Se li ki bati Ouzennchera tou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 25, text = "Berya te papa Refak ki te papa Rechèf. Rechèf te papa Tela ki te papa Takan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 26, text = "Takan te papa Layedan ki te papa Amiyoud. Amiyoud te papa Elichama", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 27, text = "ki te papa Noun. Noun te papa Jozye.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 28, text = "Pòsyon tè yo te ba yo pou yo te rete a se zòn lavil Betèl ak tout ti bouk ki sou lòd li yo, rive lavil Naaran sou bò solèy leve, lavil Gezè ak tout ti bouk ki sou lòd li yo sou bò solèy kouche, ak zòn lavil Sichèm jouk lavil Aja ak tout ti bouk ki sou lòd li yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 29, text = "Moun Manase yo te kontwole lavil Bèt Chean ak tout ti bouk ki sou lòd li yo, lavil Tanak ak tout ti bouk ki sou lòd li yo, lavil Megido ak tout ti bouk ki sou lòd li yo, ak lavil Dò ak tout ti bouk ki sou lòd li yo. Se nan lavil sa yo moun branch fanmi Jozèf, pitit Jakòb la, t'ap viv.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 30, text = "Asè te gen kat pitit gason: Imna, Ichva, Ichvi, Berya ak yon pitit fi ki te rele Sera.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 31, text = "Berya te gen de pitit gason: Ebè ak Malkyèl. Se Malkyèl sa a ki te tabli lavil Bizayit.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 32, text = "Ebè te gen twa pitit gason: Jaflè, Chomè, Otam ak yon pitit fi yon te rele Chwa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 33, text = "Jaflè te gen twa pitit gason tou: Pasak, Bimal ak Achvat.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 34, text = "Chomè, frè Jaflè a, te gen twa pitit gason tou: Wogach, Wouba ak Aram.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 35, text = "Otam, lòt frè li a, te gen kat pitit gason: Zofa, Imna, Chelèk ak Amal.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 36, text = "Men pitit Zofa yo: Swa, Anefè, Chwal, Beri, Imra,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 37, text = "Bezè, Wòd, Chama, Chilcha, Jitran, Bera.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 38, text = "Men pitit Jezè yo: Jefounè, Pispa ak Ara.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 39, text = "Men pitit Oula yo: Ara, Anyèl ak Rizya.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 7, verseNumber = 40, text = "Tout moun sa yo te moun branch fanmi Asè. Yo tout te chèf fanmi, vanyan sòlda, grannèg. Dapre rejis fanmi yo, te gen vennsimil (26.000) gason ki te gen laj pou fè sèvis lame, epi ki te bon pou fè lagè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 1, text = "Benjamen te gen senk pitit gason. Pi gran an te rele Bela, dezyèm lan Achbèl, twazyèm lan Akra,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 2, text = "katriyèm lan Nora, senkyèm lan Rafa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 3, text = "Men non pitit Bela yo: Ada, Gera, Abiyoud,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 4, text = "Abichwa, Naaman, Akora,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 5, text = "Gera, Chefoufan ak Ouram.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 6, text = "-", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 7, text = "Men non pitit Eyoud yo: Naaman, Ajija ak Gera. Yo te chèf branch fanmi ki t'ap viv nan zòn Geba a. Apre sa, yo mete yo deyò, y' al rete Manarat. Se Gera, papa Ouza ak Akiyoud, ki te mennen yo al rete Manarat la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 8, text = "-", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 9, text = "Charayim divòse ak de madanm li yo: Ouchim ak Bara. Apre sa, li al rete nan peyi Moab, li marye ak Odèch ki ba li sèt pitit gason: Jobab, Zibya, Mecha, Malkam,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 10, text = "Jeou, Sakya, Mima. Tout pitit gason l' yo te chèf fanmi.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 11, text = "Li te gen de lòt pitit gason Ouchim te fè pou li: Abitoub ak Elpal.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 12, text = "Elpal te gen twa pitit gason: Ebè, Micham ak Chèmèd. Se Chèmèd sa a ki te bati lavil Ono ak lavil Lòd ansanm ak tout ti bouk ki te sou kont li yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 13, text = "Berya ak Chema te chèf fanmi moun ki te rete lavil Ajalon. Se yo ki te mete ansyen moun ki te rete lavil Gat yo deyò.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 14, text = "Men pitit Berya yo: Akio, Chachak, Jeremòt,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 15, text = "Zebadya, Arad, Edè,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 16, text = "Michayèl, Ichpa ak Joa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 17, text = "Men non pitit Elpal yo: Zebadya, Mechoulam, Izki, Ebè,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 18, text = "Ichmerayi, Izlija ak Jobab.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 19, text = "Men pitit Chimèyi yo: Jakim, Zikri, Zabdi,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 20, text = "Elyenayi, Ziltayi, Eliyèl,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 21, text = "Adaja, Beraja ak Chimrat.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 22, text = "Men pitit Chachak yo: Ichpan, Ebè, Eliyèl,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 23, text = "Abdon, Zikri, Anan,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 24, text = "Ananya, Elam, Antotija,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 25, text = "Ifdeja ak Penwèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 26, text = "Men pitit Jeworam yo: Chamcherayi, Chearya, Atalya,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 27, text = "Jarechya, Elija ak Zikri.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 28, text = "Chak mesye sa yo te chèf fanmi yo. Yo te rete lavil Jerizalèm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 29, text = "Jeyèl te bati lavil Gabawon kote li te rete. Madanm li te rele Maaka.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 30, text = "Premye pitit gason l' lan te rele Abdon. Lòt pitit li yo te rele Zou, Kich, Nè, Nadab,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 31, text = "Gedò, Akio, Zekè", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 32, text = "ak Miklòt ki te papa Chimea. Pitit moun sa yo te rete lavil Jerizalèm bò kote moun ki te menm branch fanmi ak yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 33, text = "Nè te papa Kich ki te papa Sayil. Sayil te gen kat pitit gason: Jonatan, Malchichwa, Abinadab ak Echbaal.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 34, text = "Jonatan te papa Meribaal ki te papa Mika.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 35, text = "Mika te gen kat pitit gason: Piton, Melèk, Tarea ak Akaz.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 36, text = "Akaz te papa Jeojada ki te gen twa pitit gason: Alemèt, Azmavèt ak Zimri. Zimri te papa Moza.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 37, text = "Moza te papa Binea ki te papa Rafad. Rafad te papa Eleaza ki te papa Azèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 38, text = "Azèl te gen sis pitit gason. Se te Azrikam, Bokwou, Ichmayèl, Chearya, Obadya ak Anan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 39, text = "Echèk, frè Azèl la, te gen twa pitit gason: Oulam, Jeouch ak Elifelèt.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 8, verseNumber = 40, text = "Pitit gason Oulam yo te vanyan sòlda ki te gen anpil ladrès nan sèvi ak banza. Yo te gen sansenkant (150) pitit ak pitit pitit antou. Tout moun sa yo te fè pati branch fanmi Benjamen an.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 1, text = "Se konsa yo te make non tout moun pep Izrayèl yo dapre fanmi yo nan liv wa Izrayèl yo. Yo te depòte moun peyi Jida yo lavil Babilòn paske yo pa t' fè volonte Bondye.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 2, text = "Premye moun nan pèp Izrayèl la ki te tounen vin rete sou tè yo ak nan lavil yo se te prèt yo, moun Levi yo ak moun k'ap travay nan Tanp lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 3, text = "Se lavil Jerizalèm moun nan branch fanmi Jida, moun nan branch fanmi Benjamen, moun nan branch fanmi Efrayim ak moun nan branch fanmi Manase, yo tout al rete.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 4, text = "Nan moun Jida yo te gen Outayi, pitit gason Amiyoud. Amiyoub sa a te pitit Omri, Omri te pitit Imri, Imri te pitit gason Bani, Bani te soti nan fanmi Perèz, pitit Jida.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 5, text = "Nan fanmi Chela a te gen Asaja ki te chèf fanmi an.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 6, text = "Nan fanmi Zerak la te gen Jeoujèl ki te chèf fanmi an. Sa te fè antou sisankatrevendis (690) moun nan fanmi Jida a ki te rete lavil Jerizalèm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 7, text = "Nan moun fanmi Benjamen yo te gen Salou, pitit gason Mechoulam, ki te pitit gason Odavya, ki li menm te pitit gason Asenwa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 8, text = "Te gen Jibneja, pitit gason Jeworam, Ela, pitit gason Ouzi, pitit pitit Mikri, ak Mechoulam, pitit Chepatya, ki te pitit Reouyèl, pitit pitit Jibniya.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 9, text = "Sa te fè antou nèfsansenkannsis (956) moun nan fanmi Benjamen an ki te rete lavil Jerizalèm. Yo tout te chèf fanmi yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 10, text = "Men prèt ki t'ap viv nan lavil la. Te gen Jedaja, Jeojarib, Jaken,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 11, text = "Azarya, pitit Ilkija. Ilkija sa a te pitit Mechoulam, Mechoulam te pitit Zadòk, Zadòk te pitit Merajòt, Merajòt te pitit Achitoub. Se li menm Achitoub sa a ki te chèf nan tanp Bondye a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 12, text = "Lèfini, te gen Adaja, pitit gason Jeworam. Jeworam sa a te pitit Pachou ki te pitit Malkija. Te gen ankò Masayi, pitit Adyèl. Adyèl sa a te pitit Jazera, Jazera te pitit Mechoulam, Mechoulam te pitit Mechilemit, Mechilemit te pitit Ime.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 13, text = "Prèt sa yo ak fanmi yo te fè antou milsètsanswasant (1.760) moun ki te chèf fanmi, vanyan gason ki te bon pou sèvis kay Bondye a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 14, text = "Men moun Levi ki te rete nan lavil la. Te gen Chemaja, pitit gason Achoub. Achoub sa a te pitit Azrikam, Azrikam te pitit Achabya, nan branch fanmi Merari a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 15, text = "Te gen Bakbaka, Erès, Galal ak Matanya. Matanya sa a te pitit Mika. Mika te pitit Zikri, Zikri li menm te pitit Asaf.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 16, text = "Te gen Obadya, pitit Chemaya. Chemaya sa a te pitit Galal, Galal te pitit Jedoutoun. Pou fini, te gen Berekya, pitit Asa, ki te pitit Elkana ki te rete nan ti bouk moun Netofa yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 17, text = "Men gad ki t'ap fè pòs nan pòtay Tanp lan. Se te Chaloum, Akoub, Talmon, Akiman ak lòt fanmi yo. Se Chaloum ki te chèf yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 18, text = "Jouk jounen jòdi a se yo k'ap fè pòs nan Pòtay Wa ki bay sou bò solèy leve a, kote pou wa a pase a. Nan tan lontan, se yo menm ki te konn fè pòs nan Pòtay Kay moun Levi yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 19, text = "Chaloum, pitit Kore, pitit pitit Ebyazaf nan branch fanmi Kore a, ansanm ak lòt moun nan fanmi Kore a te reskonsab veye pòtay pou antre nan kote ki apa pou Seyè a, tankou zansèt yo te fè l' anvan sa lè yo t'ap veye Pòtay kan Seyè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 20, text = "Yon lè se Fineas, pitit Eleaza a, ki te chèf yo. Seyè a te toujou kanpe avè l'.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 21, text = "Zakari, pitit Mechelemya, te gad nan pòtay Tant Randevou a tou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 22, text = "Antou te gen desandouz (212) gason yo te chwazi pou fè pòs nan pòtay tanp lan, dapre liv rejis fanmi yo nan ti bouk kote yo moun. Se wa David ak pwofèt Samyèl ki te bay zansèt yo reskonsablite sa a pou tout tan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 23, text = "Se konsa, yo menm ak pitit yo yo toujou ap fè pòs nan pòtay Tanp lan, nan pòtay Tant Randevou a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 24, text = "Te gen kat pòtay ki te bay sou kat bòn direksyon yo: lès, lwès, nò ak sid. Pou chak pòtay te gen yon chèf gad.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 25, text = "Fanmi yo ki te rete nan ti bouk yo te vin ede yo nan travay la pandan sèt jou, yonn apre lòt.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 26, text = "Men, kat chèf gad yo te toujou la desèvis. Se moun fanmi Levi yo te ye. Se yo ki te reskonsab tout pyès chanm ansanm ak tout trezò ki te la nan Tanp lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 27, text = "Yo te rete pase nwit yo toupre Tanp lan, paske se yo ki te reskonsab veye l'. Lèfini, chak maten se yo ki pou te louvri pòtay yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 28, text = "Te gen lòt moun Levi ki te reskonsab tout veso yo sèvi pou fè seremoni yo. Se pou yo te kontwole yo ni anvan ni apre chak seremoni yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 29, text = "Te gen lòt moun Levi ki te reskonsab tout rès bagay ki te nan Tanp lan ansanm ak farin frans, diven, lwil oliv, lansan ak odè yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 30, text = "Men, se prèt yo ki te reskonsab pare odè yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 31, text = "Se yon moun Levi yo te rele Matitya, premye pitit Chaloum nan fanmi Kore a, ki te toujou reskonsab fè gato pou ofrann yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 32, text = "Lòt moun Levi nan fanmi Keyat la te reskonsab pare pen pou yo te mete chak jou repo nan Tanp lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 33, text = "Genyen nan fanmi Levi yo ki te sanba. Chèf fanmi sa yo te viv nan pyès chanm ki te nan Tanp lan. Yo pa t' gen lòt okipasyon pase lajounen kou lannwit yo t'ap fè travay yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 34, text = "Tout mesye sa yo te chèf fanmi moun Levi yo, dapre zansèt yo rive jòdi a. Yo te rete lavil Jerizalèm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 35, text = "Jeyèl te bati lavil Gabawon kote li te rete. Madanm li te rele Maaka.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 36, text = "Premye pitit gason l' lan te rele Abdon. Lòt pitit li yo te rele Zou, Kich, Baal, Nè, Nadak,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 37, text = "Gedò, Akio, Zèkè ak Miklòt.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 38, text = "Se Miklòt sa a ki te papa Chimeam. Pitit moun sa yo te rete lavil Jerizalèm bò kote moun ki te menm branch fanmi ak yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 39, text = "Nè te papa Kich ki te papa Sayil. Sayil te gen kat pitit gason: Jonatan, Malchichwa, Abinadab ak Echbaal.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 40, text = "Jonatan te papa Meribaal ki te papa Mika.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 41, text = "Mika te gen kat pitit gason: Piton, Melèk, Tarea ak Akaz.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 42, text = "Akaz te papa Jeojada ki te gen twa pitit gason: Alemèt, Azmavèt ak Zimri. Zimri te papa Moza.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 43, text = "Moza te papa Binea ki te papa Rafad. Rafad te papa Eleaza ki te papa Azèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 9, verseNumber = 44, text = "Azèl te gen sis pitit gason. Se te Azrikam, Bokewou, Ichmayèl, Chearya, Obadya ak Anan, Se non pitit gason Azèl yo sa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 10, verseNumber = 1, text = "Moun Filisti yo leve yon sèl batay ak moun pèp Izrayèl yo sou mòn Gilboa. Anpil nan moun pèp Izrayèl yo te mouri, rès yo te kouri met deyò.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 10, verseNumber = 2, text = "Moun Filisti yo rive sou Sayil ak pitit gason l' yo. Yo touye Jonatan, Abinadab ak Malchichwa frèt.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 10, verseNumber = 3, text = "Batay la te mangonmen kote Sayil te ye a. Mesye ki t'ap voye flèch nan banza yo te konmanse ap vize sou li. Lè li wè sa, li pran tranble.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 10, verseNumber = 4, text = "Li rele gad kò ki t'ap pote zam li yo, li di l' konsa: -Rale nepe ou, touye m' pou bann moun sa yo ki pa sèvi Bondye pa gen tan rive sou mwen pou yo pase m' nan betiz. Men, gad kò a pa t' vle paske li te pè anpil. Lè sa a, Sayil pran nepe a, li vire l' tèt anba, li lage kò l' sou li.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 10, verseNumber = 5, text = "Lè gad kò a wè Sayil te mouri, li fè menm bagay la tou, li lage kò l' sou nepe pa li a, li mouri ansanm ak Sayil.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 10, verseNumber = 6, text = "Se konsa, ni Sayil ni twa pitit gason l' yo te mouri. Jou sa a, tout mesye Sayil yo te mouri.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 10, verseNumber = 7, text = "Moun pèp Izrayèl yo ki te rete nan fon an te wè sòlda pèp Izrayèl yo kouri epi Sayil ak pitit gason l' yo mouri. Lè sa a, yo leve kite lavil kote yo te rete yo, yo met deyò. Moun Filisti yo vini, yo pran lavil yo pou yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 10, verseNumber = 8, text = "Nan denmen apre batay la, moun Filisti yo tounen pou pran zam ki te sou kadav sòlda mouri yo, yo jwenn kadav Sayil ak kadav twa pitit gason l' yo kouche atè sou mòn Gilboa a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 10, verseNumber = 9, text = "Yo koupe tèt Sayil, yo pran tout zam li yo. Lèfini, yo voye gaye bon nouvèl sa a nan tout peyi Filisti a, nan tanp zidòl yo ak nan zòrèy tout pèp la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 10, verseNumber = 10, text = "Yo mete zam Sayil yo nan tanp Astate, zidòl yo a. Epi yo pran tèt li, yo kloure l' nan tanp Dagon an.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 10, verseNumber = 11, text = "Lè moun lavil Jabès yo, nan peyi Galarad, vin konnen sa moun Filisti yo te fè Sayil,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 10, verseNumber = 12, text = "tout mesye ki te brave danje yo leve, y' al pran kadav Sayil la ansanm ak kadav pitit gason l' yo, yo tounen ak yo lavil Jabès. Yo antere zosman yo anba pye tonmaren ki nan lavil Jabès la. Apre sa, yo pase sèt jou san manje.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 10, verseNumber = 13, text = "Se konsa Sayil mouri paske li pa t' kenbe pawòl li ak Seyè a. Li pa t' obeyi lòd Seyè a te ba li. Li te pito fè yo rele nanm moun mouri pou l' te konnen sa ki tapral rive l',", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 10, verseNumber = 14, text = "pase pou l' te al mande Seyè a sa. Se poutèt sa Seyè a te touye l', li renmèt gouvènman an nan men David, pitit lzayi a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 1, text = "Tout branch fanmi Izrayèl yo vin jwenn David lavil Ebwon, yo di l' konsa: -Nou se moun menm ras, menm fanmi avè ou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 2, text = "Depi lontan, menm sou rèy wa Sayil, se ou menm ki te kòmande lame pèp Izrayèl la kote l' ale. Lèfini ankò, Seyè a, Bondye ou la, te pwomèt se ou menm ki pral gouvènen pèp li a, pèp Izrayèl la. Se ou menm ki pral chèf yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 3, text = "Se konsa, tout chèf fanmi pèp Izrayèl yo vin jwenn David lavil Ebwon. Yo pase yon kontra avè l' devan Seyè a. Yo fè seremoni, yo mete l' wa sou pèp Izrayèl la tou, jan Seyè a te fè pwomès la nan bouch pwofèt Samyèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 4, text = "David mache sou lavil Jerizalèm ansanm ak tout moun pèp Izrayèl yo. Lè sa a, lavil la te rele Jebis. Se moun Jebis yo, premye moun ki te rete nan peyi a, ki t'ap viv la toujou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 5, text = "Moun Jebis yo te di David: Ou p'ap janm ka rive antre nan lavil nou an. Men David pran gwo fò ki te sou tèt mòn Siyon an. Se li yo rele lavil David la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 6, text = "David pou tèt pa l' te di premye moun ki va atake moun Jebis yo, l'ap mete l' chèf, moun sa a ap grannèg nan gouvènman l' lan. Joab, pitit gason Sewouya a, te premye moun ki atake. Se konsa li vin chèf.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 7, text = "Apre sa, David al rete nan fò a. Se poutèt sa yo rele l' lavil David la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 8, text = "Lèfini, li bati lòt kay fè wonn fò a, depi sou teras la rive bò palè a. Joab menm rebati rès lavil la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 9, text = "Chak jou David t'ap vin pi fò. Seyè a, Bondye ki gen tout pouvwa a, te kanpe avè l'.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 10, text = "Men non chèf vanyan sòlda David yo. Se yo ki te soutni gouvènman David la ansanm ak tout pèp Izrayèl la pou l' te ka wa, jan Seyè a te pwomèt moun Izrayèl yo sa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 11, text = "Pou konmanse, te gen Jakobeyam ki soti nan branch fanmi Akmoni an. Se li menm ki te chèf twa pi vanyan yo. Pou kont li, li batay ak twasan (300) moun ak frenn li ase. Li touye yo tout yon sèl kou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 12, text = "Dezyèm lan te rele Eleaza, pitit gason Dodo, pitit yon moun lavil Akwo. Se te yonn nan twa pi vanyan yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 13, text = "Li te avèk David lè David t'ap goumen ak moun Filisti yo nan batay bò Pasdamen an. Li te nan yon jaden lòj lè sòlda pèp Izrayèl yo konmanse kouri devan moun Filisti yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 14, text = "Se konsa, li menm ak sòlda li yo, yo tout rete kanpe nan mitan jaden lòj la, yo kenbe tèt ak moun Filisti yo, yo bat yo byen bat, yo kraze yo. Se konsa Seyè a te fè yo genyen batay la sou lènmi yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 15, text = "Yon lòt jou, nan sezon rekòt, twa nan gwoup Trant yo al jwenn David nan gwòt Adoulam lan. Lame moun Filisti yo te moute kan yo nan plenn moun Refayim yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 16, text = "Lè sa a, David te nan fò a. Yon gwoup moun Filisti te pran lavil Betleyèm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 17, text = "Yon sèl anvi pran David, li di konsa: -Ki moun ki va fè m' bwè ti gout dlo nan pi ki nan pòtay lavil Betleyèm lan?", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 18, text = "Lamenm twa mesye yo desann, yo fofile kò yo nan mitan moun Filisti yo, yo pran dlo nan pi ki te nan pòtay lavil Betleyèm lan, yo pote l' vin bay David. Men, David refize bwè dlo a. Li vide l' atè, li ofri l' bay Seyè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 19, text = "Li di konsa: -Seyè, mwen pa gen dwa bwè dlo sa a. Se tankou si m' ta bwè san mesye sa yo ki riske lavi yo pou y' al chache l'. Se konsa, li derefize bwè dlo a. Se sa twa vanyan gason sa yo te fè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 20, text = "Abichayi, frè Joab, te chèf trant vanyan yo. Pou kont li, avèk yon frenn nan men l', li goumen ak twasan (300) moun, li touye yo. Se konsa, tout moun t'ap nonmen non l' nan gwoup Trant vanyan yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 21, text = "Se li menm ki te resevwa plis lwanj nan Trant vanyan yo. Apre sa, li vin chèf yo. Men, li pa janm rive fè sa twa pi vanyan yo te fè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 22, text = "Benaja, pitit gason Jeojada a, moun lavil Kabseyèl, te pitit pitit yon vanyan sòlda. Li te fè anpil bagay ki fè wè li pa t' manke kouraj. Se li menm ki te touye de pitit Ariyèl yo, moun lavil Moab. Yon jou, lanèj t'ap tonbe, li desann nan yon sitèn dlo al touye yon lyon.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 23, text = "Li touye tou yon moun peyi Lejip, yon gwo potorik gason sèt pye sis pous wotè, ki te gen yon gwo frenn nan men li. Frenn lan te gen yon manch menm gwosè ak yon gwo mach pilon. Benaja menm al atake li ak yon baton ase. Li wete lans lan nan men moun peyi Lejip la, epi li touye l' avè l'.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 24, text = "Men sa Benaja, pitit gason Jeojada a, te fè. Se konsa, tout moun t'ap nonmen non l' nan gwoup Trant Vanyan yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 25, text = "Se non li yo t'ap nonmen pi plis nan Trant Vanyan yo. Apre sa, li vin chèf yo. Men, li pa t' janm rive fè sa twa pi vanyan yo te fè. David te mete l' nan gad kò li.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 26, text = "Men non lòt vanyan sòlda yo: Asayèl, frè Joab la, Elanan, pitit gason Dodo, moun lavil Betleyèm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 27, text = "Chamòt, moun lavil Awòd, Elèz, moun lavil Palon,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 28, text = "Ira, pitit gason Ikèch, moun lavil Tekoa, Abyezè, moun lavil Anatòt,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 29, text = "Sibekayi, moun lavil Oucha, Ilayi, moun lavil Awoya,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 30, text = "Marayi, moun lavil Netofa, Elèb, pitit gason Bana, moun lavil Netofa,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 31, text = "Itayi, pitit gason Ribayi, moun lavil Gibeya nan pòsyon tè ki pou branch fanmi Benjamen yo, Benaja, moun lavil Piraton,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 32, text = "Ourayi, moun ravin Gach yo, Abiyèl, moun lavil Araba,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 33, text = "Azmavèt, moun lavil Baawoum, Elyaba, moun lavil Chalbon,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 34, text = "Pitit gason Achèm yo, moun lavil Gizon, Jonatan, pitit gason Chage, moun lavil Ara,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 35, text = "Akiyam, pitit gason Saka, moun lavil Ara, Elifal, pitit gason Our,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 36, text = "Efè, moun lavil Mekera, Akija, moun lavil Palon,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 37, text = "Ezwo, moun lavil Kamèl, Narayi, pitit gason Esbayi,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 38, text = "Joèl, frè Natan an, Mibka, pitit gason Agri,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 39, text = "Zelèk, moun lavil Amon, Nakarayi, moun lavil Bewòt. Se li menm ki te pote zam Joab, pitit gason Sewouya a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 40, text = "Ira ak Garèb, nan fanmi Jetè a,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 41, text = "Ouri, moun lavil Et la, Zabad, pitit Aklayi,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 42, text = "Adina, pitit Siza, yon chèf nan branch fanmi Woubenn lan, ak yon gwoup trant moun avè l'.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 43, text = "Anan, pitit gason Maka, Jozafa, moun lavil Mitni,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 44, text = "Ouzya, moun lavil Astawòt, Sama ak Jeyèl, pitit gason Otam, moun lavil Awoyè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 45, text = "Jedyayèl ak Joa, frè li, tou de pitit gason Chimri, moun lavil Tiz.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 46, text = "Eliyèl, moun lavil Manayim, Jeribayi ak Josavya, pitit gason Elnam, Jitma, moun lavil Moab,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 11, verseNumber = 47, text = "Eliyèl, Obèd ak Jasiyèl, moun lavil Soba.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 1, text = "Lè David t'ap viv lavil Ziklag kote li te al kache pou Sayil, pitit gason Kich la, pa jwenn li, yon bann vanyan sòlda te vin jwenn li la pou ba l' konkou nan lagè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 2, text = "Yo tout te gen banza. Yo te gen ladrès pou voye wòch ak pou tire flèch ni ak men gòch ni ak men dwat. Se te moun branch fanmi Benjamen yo te ye tankou Sayil.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 3, text = "Alatèt yo te gen Akyezè ak Joas, pitit gason Chema, moun lavil Gibeya, Jezyèl ak Pelèt, pitit gason Azmavèt, Beraka ak Jeou, moun lavil Anatòt,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 4, text = "Jismaja, moun lavil Gabawon, yonn nan trant vanyan sòlda yo ak yonn nan chèf yo, Jeremi, Jakazyèl, Joanan ak Jozabad, moun lavil Gedera.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 5, text = "Elouzayi, Jerimòt, Bealya, Chemarya ak Chefatya, moun lavil Awòf,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 6, text = "Elkana, Jichija, Azariyèl, Joezè ak Jakobeyam, nan branch fanmi Kore a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 7, text = "Joela ak Zebadya, pitit gason Jewokam, moun lavil Gedò.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 8, text = "Konsa tou, nan branch fanmi Gad la, te gen moun ki te pati al jwenn David lè li te nan fò nan dezè a. Se te yon bann vanyan sòlda ki te gen ladrès nan fè lagè. Yo tout te gen plak pwotèj ak frenn. Yo te move tankou lyon, yo te konn kouri tankou kabrit nan mòn.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 9, text = "Premye a te rele Ezè, dezyèm lan Obadya, twazyèm lan Eliyab,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 10, text = "katriyèm lan Michmana, senkyèm lan Jeremi,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 11, text = "sizyèm lan Atayi, setyèm lan Eliyèl,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 12, text = "wityèm lan Jokanan, nevyèm lan Elzabad,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 13, text = "dizyèm lan Jeremi, onzyèm lan Makbanayi.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 14, text = "Mesye branch fanmi Gad yo te chèf nan lame a. Pi piti ladan yo a te vo san (100) sòlda, pi gran an te vo mil (1000) sòlda.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 15, text = "Se yo menm ki te janbe lòt bò larivyè Jouden an yon lè larivyè a t'ap desann nan premye mwa lanne a. Lèfini, yo fè tout moun ki te rete nan fon yo mete deyò, ni sou bò solèy leve, ni sou bò solèy kouche.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 16, text = "Nan branch fanmi Benjamen ak branch fanmi Jida yo te gen moun ki te vin jwenn David jouk nan fò kote l' te kache a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 17, text = "David soti al kontre yo, li di yo: -Si se an zanmi nou vini pou ede m', m' byen kontan nou vin jwenn mwen. Men, si se pou nou trayi m' bay moun ki pa vle wè m' yo, mwen menm mwen konnen mwen pa fè ankenn mechanste, mwen lapriyè Bondye ak tout kè m'. Bondye zansèt nou yo va wè sa, se li ki va pini nou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 18, text = "Lè sa a, lespri Bondye desann sou Amasayi, chèf trant vanyan yo, li di byen fò: -Nou la avè ou, David! Nou kanpe avè ou, pitit Izayi! Kè poze pou ou ak pou moun k'ap ede ou yo! Paske Bondye te pote ou sekou! Lè sa a, David resevwa yo, li mete yo chèf nan lame li a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 19, text = "Nan branch fanmi Manase a, te gen moun ki te vin jwenn David lè li te mete tèt ansanm ak moun Filisti yo pou goumen ak Sayil. Men, lè sa a, David pa t' bay moun Filisti yo ankenn konkou. Lè gwo chèf moun Filisti yo reyini pou koze sou zafè a, yo te pran desizyon di l' non mèsi, paske yo t'ap di li ta ka vann yo pou li te ka byen anko ak Sayil, mèt li.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 20, text = "Men moun nan branch fanmi Manase a ki te vin mete tèt ansanm ak David apre li te tounen lavil Ziglag. Se te Adnak, Jozabad, Jedyayèl, Mikayèl, Jozabad, Eliyou ak Siltayi, ki te chèf rejiman mil sòlda laba nan peyi Manase.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 21, text = "Se yo menm ki te ede David ansanm ak lame a, paske se te yon bann vanyan sòlda. Apre sa, yo te gwo chèf nan lame a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 22, text = "Se chak jou moun t'ap vin jwenn David pou ede l'. Se konsa li vin gen yon gwo lame ak anpil anpil moun ladan l'.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 23, text = "Men kantite moun avèk zam pou fè lagè ki te vin jwenn David lavil Ebwon pou renmèt li gouvènman an nan plas Sayil, jan Seyè a te bay lòd la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 24, text = "Nan branch fanmi Jida a, similwisan (6.800) gason avèk plak pwotèj yo ak frenn yo, tout byen pare pou fè lagè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 25, text = "Nan branch fanmi Simeyon an, sètmilsan (7.100) vanyan sòlda byen pare pou fè lagè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 26, text = "Nan branch fanmi Levi a, katmilsisan (4.600),", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 27, text = "plis twamilsètsan (3.700) nan fanmi Mawon an ak Jeojada alatèt yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 28, text = "Te gen Zadòk tou, yon jenn vanyan gason ak vennde lòt chèf nan fanmi li.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 29, text = "Nan branch fanmi Benjamen an, fanmi Sayil la menm, twamil (3.000) gason. Pifò nan moun fanmi Benjamen yo te kanpe toujou avèk Sayil.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 30, text = "Nan branch fanmi Efrayim lan, venmilwisan (20.800) vanyan sòlda. Tout moun t'ap nonmen non yo nan fanmi yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 31, text = "Nan mwatye branch fanmi Manase a, dizwimil (18.000) gason yo te chwazi pou al mete David wa sou fotèy la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 32, text = "Nan branch fanmi Isaka a, moun ki te fò nan konnen sa pou pèp Izrayèl la fè ak lè pou yo fè l', desan (200) chèf ansanm ak tout gason nan branch fanmi an ki te sou kòmandman yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 33, text = "Nan branch fanmi Zabilon an, senkantmil (50.000) sòlda ki konn mache fè lagè avèk tout kalite zam, epi ki te soti pou ede David ak tout kè yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 34, text = "Nan branch fanmi Neftali a, mil (1000) chèf ansanm ak trannsètmil (37.000) gason ak plak pwotèj ak frenn.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 35, text = "Nan branch fanmi Dann lan ventwimilsisan (28.600) sòlda.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 36, text = "Nan branch fanmi Asè a, karantmil (40.000) sòlda ki konn mache fè lagè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 37, text = "Lèfini, nan branch fanmi Woubenn lan, nan branch fanmi Gad la, ak nan mwatye branch fanmi Manase a ki te lòt bò larivyè Jouden an te gen sanvenmil (120.000) gason ak tout kalite zam.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 38, text = "Tout sòlda sa yo, ki te tou pare pou fè lagè, te vin jwenn David lavil Ebwon ak tout kè yo. Yo te soti pou yo te fè l' wa sou tout peyi Izrayèl la. Tout rès pèp Izrayèl la te vini ak menm lide a tou: fè David wa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 39, text = "Yo pase twa jou la ansanm ak David, yo t'ap manje, yo t'ap bwè, paske moun Izrayèl parèy yo te pare tout bagay pou yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 12, verseNumber = 40, text = "Lèfini, moun soti nan tout vwazinaj la, jouk nan peyi Isaka, peyi Zabilon ak peyi Neftali, yo pote manje sou bourik, sou chamo, sou milèt ak sou bèf. Te gen pwovizyon farin frans, gato, fig frans, grap rezen chèch, diven, lwil ak kantite bèf, mouton ak kabrit. Tout pèp Izrayèl la t'ap fè fèt nan tout peyi a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 13, verseNumber = 1, text = "David reyini tout chèf lamè a, ni sa ki te alatèt rejiman mil (1000) sòlda yo ni sa ki te alatèt divizyon san sòlda yo, li pran konsèy nan men yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 13, verseNumber = 2, text = "Lèfini, David di pèp Izrayèl la: -Si nou wè se yon bon lide, si se volonte Seyè a, Bondye nou an, nou pral voye misyon bay tout frè nou yo ki rete toupatou nan tout peyi a, bay tout prèt yo ak tout moun Levi yo nan lavil kote yo rete ak nan savann kote yo fè gadinaj, pou yo vin mete tèt yo ansanm ak nou,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 13, verseNumber = 3, text = "pou n' al chache Bwat Kontra Bondye nou an, paske nou te bliye l' pandan tout rèy Sayil la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 13, verseNumber = 4, text = "Tout pèp la te dakò pou yo te fè sa, paske yo wè se te yon bon lide.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 13, verseNumber = 5, text = "Se konsa, David reyini tout pèp Izrayèl la nan tout peyi a, depi kannal Sikò sou fwontyè ak peyi Lejip la rive jouk Pas Amat la, pou y' al chache Bwat Kontra a lavil Kiriyat-Jarim.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 13, verseNumber = 6, text = "Se konsa li pati avèk tout pèp Izrayèl la, pou lavil Kiriyat-Jarim yo te rele Baala tou, nan peyi Jida, pou y' al chache Bwat Kontra Bondye a, bwat ki pote non Seyè ki gen tout pouvwa a, Seyè ki gen fotèy li anwo zanj cheriben yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 13, verseNumber = 7, text = "Lè yo rive kay Abinadab, yo pran Bwat la, yo mete l' sou yon kabwa tou nèf. Ouza ak Akijo t'ap mennen kabwa a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 13, verseNumber = 8, text = "David ansanm ak tout moun Izrayèl yo menm t'ap danse ak tout nanm yo. Yo t'ap chante fè lwanj Seyè a, yo t'ap jwe gita ak bandjo, yo t'ap bat tanbouren ak senbal, yo t'ap kònen twonpèt.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 13, verseNumber = 9, text = "Lè yo rive bò glasi Kidon an, bèf yo bite, yo manke tonbe. Ouza lonje men l' pou kenbe Bwat Kontra a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 13, verseNumber = 10, text = "Men, Seyè a move sou Ouza, li touye l' frèt, paske li pa t' dwe manyen Bwat Kontra a. Bondye touye l', Ouza mouri la menm devan Bondye.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 13, verseNumber = 11, text = "David menm te fache dèske Seyè a te touye Ouza. Se konsa yo rele kote sa a Perèz-Ouza. Non sa a rete jouk jounen jòdi a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 13, verseNumber = 12, text = "Lè sa a, David vin pè Seyè a, li di konsa: -M' pa wè ki jan pou m' pran Bwat Kontra a avè m' koulye a!", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 13, verseNumber = 13, text = "Se konsa, li pran desizyon pa pote Bwat Kontra Seyè a lakay li nan lavil David. Li fè yo pote l' kay Obèd-Edon, yon moun lavil Gat.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 13, verseNumber = 14, text = "Bwat la pase twa mwa lakay Obèd-Edon, Seyè a te beni fanmi Obèd-Edon ak tout bagay ki te pou yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 14, verseNumber = 1, text = "Iram, wa lavil Tir la, delege kèk mesaje bò kote David ak yon chajman bwa sèd. Li voye tou kèk bòs mason ak bòs chapant pou bati yon palè pou li.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 14, verseNumber = 2, text = "Lè sa a atò, David wè tout bon vre se Seyè a menm ki te mete l' wa pèp Izrayèl la, epi ki te fè tout bagay mache byen pou gouvènman li, akòz pèp Bondye a, pèp Izrayèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 14, verseNumber = 3, text = "Lè David te lavil Jerizalèm, li pran lòt madanm ki ba li lòt pitit gason ak lòt pitit fi.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 14, verseNumber = 4, text = "Men non pitit David ki te fèt lavil Jerizalèm: Chamwa, Choba, Natan, Salomon,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 14, verseNumber = 5, text = "Jibka, Elichwa, Elpelèt,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 14, verseNumber = 6, text = "Noga, Nefèg, Jafya,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 14, verseNumber = 7, text = "Elichama, Baalyada ak Elifelèt.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 14, verseNumber = 8, text = "Lè moun Filisti yo vin konnen yo te mete David wa pou tout pèp Izrayèl la, yo tout yo leve pou y' al mete men sou li. Lè David li menm pran nouvèl la, li soti al kontre yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 14, verseNumber = 9, text = "Moun Filisti yo rive, yo anvayi tout fon Refayim lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 14, verseNumber = 10, text = "David pale ak Bondye, li mande l': -Eske se pou m' atake moun Filisti yo? Eske w'ap lage yo nan men m'? Seyè a reponn li: -Wi, atake yo. M'ap lage yo nan men ou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 14, verseNumber = 11, text = "David moute Baal Perazim, li kraze moun Filisti yo. Le sa a, David di: -Tankou yon lavalas, Bondye sèvi avè m' pou l' louvri yon pasaj nan mitan lènmi m' yo. Se poutèt sa yo rele kote sa a Baal Perazim.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 14, verseNumber = 12, text = "Moun Filisti yo te kouri kite zidòl yo dèyè. David bay lòd pou yo boule yo nan dife.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 14, verseNumber = 13, text = "Apre sa, moun Filisti yo tounen nan fon an ankò pou fè piyay.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 14, verseNumber = 14, text = "David mande Bondye sa pou li fè. Bondye di li: -Pa atake yo pa devan bò isit la. Fè yon detou, pase pa dèyè yo. W'a atake yo bò pye gayak yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 14, verseNumber = 15, text = "Lè w'a tande yon bri tankou bri pye yon moun k'ap mache sou tèt pyebwa yo, w'a fonse sou yo. Paske sa vle di se mwen menm Bondye k'ap pran devan ou pou bat lame moun Filisti yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 14, verseNumber = 16, text = "David fè sa Seyè a te mande l' fè a. Yo bat lame moun Filisti yo, yo kouri dèyè yo depi lavil Geba rive lavil Gezè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 14, verseNumber = 17, text = "Se konsa toupatou yo t'ap nonmen non wa David. Seyè a te fè tout nasyon yo pè li.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 1, text = "David fè yo bati anpil kay pou li nan lavil David la. Li pare yon anplasman pou Bwat Kontra Bondye a, li moute yon gwo tant twal pou li.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 2, text = "Epi li di: -Se moun Levi yo ase ki pou pote Bwat Kontra Bondye a, paske se yo menm Seyè a te chwazi pou pote Bwat la, se yo li te chwazi pou sèvi l' pou tout tan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 3, text = "Lèfini, li reyini tout pèp Izrayèl la lavil Jerizalèm pou yo pote Bwat Kontra a kote li te pare pou li a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 4, text = "Apre sa, li voye chache tout moun nan ras fanmi Arawon yo ansanm ak moun Levi yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 5, text = "Nan branch fanmi Keyat la, te gen Ouryèl, chèf la, ak tout fanmi l' yo. Sa te fè antou sanven (120).", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 6, text = "Nan branch fanmi Merari a, te gen Asaja, chèf la, ak tout fanmi l' yo. Sa te fè antou desanven (220).", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 7, text = "Nan branch fanmi Gèchon an, te gen Joèl, chèf la, ak tout fanmi l' yo. Sa te fè antou santrant (130).", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 8, text = "Nan branch fanmi Elizafan an, te gen Semaja, chèf la, ak tout fanmi l' yo. Sa te fè antou desan (200).", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 9, text = "Nan branch fanmi Ebwon an, te gen Eliyèl, chèf la, ak tout fanmi l' yo. Sa te fè antou katreven.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 10, text = "Nan branch fanmi Ouzyèl la te gen Aminadad, chèf la, ak tout fanmi l' yo. Sa te fè antou sandouz (112).", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 11, text = "David rele Zadòk ak Abyata, prèt yo, ansanm ak sis moun Levi: Ouryèl, Asaja, Joèl, Chemaja, Eliyèl ak Aminadad.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 12, text = "Li di yo: -Se nou menm ki chèf branch fanmi Levi yo. Mete nou nan kondisyon pou fè sèvis pou Bondye, nou menm ansanm ak tout moun nan fanmi nou, pou nou ka al pote Bwat Kontra Seyè a, Bondye pèp Izrayèl la, kote mwen fè pare pou li a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 13, text = "Premye fwa a, nou pa t' la. Se poutèt sa Seyè a, Bondye nou an, te touye kèk nan nou paske nou pa t' fè l' jan nou te dwe fè l' la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 14, text = "Se konsa, prèt yo ak moun Levi yo al mete yo nan kondisyon pou fè sèvis Bondye, pou yo te ka al pote Bwat Kontra Seyè a, Bondye pèp Izrayèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 15, text = "Yo mete Bwat la sou gwo travès long yo, yo leve l' mete l' sou zepòl yo, yo pote l' ale jan Moyiz te ba yo lòd fè l' la dapre pawòl Seyè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 16, text = "David bay chèf moun Levi yo lòd pou yo chwazi divès moun nan fanmi yo ki konn chante, pou yo vini ak enstriman mizik yo, gita, bandjo ak senbal, pou jwe mizik cho paske kè tout moun te kontan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 17, text = "Moun Levi yo chwazi Eyman, pitit gason Joèl la, ansanm ak Asaf, pitit gason Berekya, yon fanmi Eyman, ak Etan, pitit gason Kouchaja nan branch fanmi Merari a, fanmi ak de lòt premye yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 18, text = "Apre sa, yo chwazi lòt moun Levi nan menm fanmi ak premye yo, pou ede yo nan travay yo. Se te Zakari, Aziyèl, Semiramòt, Jekiyèl, Ouni, Eliyab, Benaja, Maseja, Matitya, Elifeleou, Mikneja, ak de gad pòtay tanp lan, Obèd-Edon ak Jeyèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 19, text = "Eyman, Asaf ak Etan, sanba yo, te reskonsab pou bat senbal kwiv yo pou fè mizik.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 20, text = "Zakari, Aziyèl, Semiramòt, Jekiyèl, Ouni, Eliyab, Maseja ak Benaja t'ap jwe premye gita yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 21, text = "Matitya, Elifeleou, Mikneja, Obèd-Edon, Jeyèl ak Azazya t'ap jwe gita bas. Se yo ki pou te bay kadans chante yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 22, text = "Se Kenanya, chèf moun Levi ki te reskonsab pote Bwat la, ki t'ap dirije yo, paske li te fò nan fè travay konsa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 23, text = "Se Berekya ak Elkana ki t'ap pote Bwat Kontra a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 24, text = "Men non prèt yo te chwazi pou kònen twonpèt devan Bwat Kontra a. Se te Chebanyas, Jozafa, Netaneyèl, Amasayi, Zakari, Benaja ak Elyezè. Obèd-Edon ak Jebija te la pou pote Bwat Kontra a tou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 25, text = "Se konsa David ak tout chèf fanmi pèp Izrayèl yo ansanm ak tout chèf rejiman mil sòlda yo ale lakay Obèd-Edon, yo pran Bwat Kontra a pou yo pote l' lavil Jerizalèm ak kè kontan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 26, text = "Yo touye sèt towo ak sèt belye pou Bondye te ka ede moun Levi ki t'ap pote Bwat Kontra a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 27, text = "David te gen yon rad fèt ak twal fin blan sou li, menm jan ak tout moun Levi yo ki t'ap mache devan Bwat Kontra a, sanba yo ak Kenaja ki t'ap dirije travay transpò a. David te gen yon moso twal fin blan tou mare nan ren li.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 28, text = "Se konsa, tout pèp Izrayèl la ale ansanm ak Bwat Kontra Seyè a, yo pote l' lavil Jerizalèm. Yo t'ap rele, yo t'ap fè fèt. Yo t'ap jwe klewon, twonpèt, senbal, gita ak bandjo sou tout wout la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 15, verseNumber = 29, text = "Antan yo t'ap antre ak Bwat Kontra a lavil Jerizalèm, Mikal, pitit fi Sayil la, te kanpe bò yon fennèt ap gade. Li wè David ki t'ap danse fè laviwonn devan Bwat la. Li vin pa gen yon san pou li ankò.", bookId = 13)
    )

    private val part2 = listOf(
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 1, text = "Yo pote Bwat Kontra Seyè a, yo mete l' nan plas li nan tant David te moute pou li a. Apre sa, yo ofri bèt pou boule nèt pou Bondye, ak ofrann pou di Bondye mèsi.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 2, text = "Lè David fin fè ofrann sa yo, li beni pèp la nan non Seyè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 3, text = "Li separe manje bay tout moun pèp Izrayèl yo, fanm kou gason. Li bay yo chak yon pen, yon moso vyann woti ak yon pen rezen.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 4, text = "David chwazi kèk moun Levi pou reskonsab sèvis y'ap fè devan Bwat Kontra a pou Seyè a, Bondye pèp Izrayèl la, pou adore l', pou di l' mèsi, pou fè lwanj li.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 5, text = "Li mete Asaf chèf ak Zakari pou vin apre li. Sou zòd yo te gen Aziyèl, Chemiramòt, Jekiyèl, Matitya, Eliyab, Benaja, Obèd-Edon, Jeyèl pou jwe enstriman mizik yo, gita ak bandjo. Asaf menm t'ap bat senbal ki fè gwo bri yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 6, text = "Se Benaja ak Jaziyèl, prèt yo, ki te pou kònen twonpèt devan Bwat Kontra Bondye a tout tan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 7, text = "Se lè sa a, pou premye fwa, David te bay Asaf ak lòt moun Levi yo reskonsablite pou yo fè lwanj Seyè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 8, text = "Lwanj pou Seyè a! Fè konnen jan li gen pouvwa! Fè nasyon yo konnen sa li fè!", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 9, text = "Chante pou li! Fè lwanj li! Rakonte tout bèl bagay li te fè yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 10, text = "Fè kè nou kontan, paske nou se moun pa l'. Wi, se pou tout moun k'ap sèvi Seyè a fè fèt.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 11, text = "Ale jwenn Seyè a pou l' ka ede nou. Toujou chache rete devan li.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 12, text = "-", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 13, text = "Nou menm, pitit pitit Izrayèl, sèvitè Bondye a, Nou menm, pitit pitit Jakòb yo, nou menm Bondye chwazi yo, chonje mirak ak bèl bagay li te fè yo. Chonje jijman ki te soti nan bouch li.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 14, text = "Seyè a, se Bondye nou li ye. Lè li pase yon lòd, se pou tout latè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 15, text = "Toujou chonje kontra li a. L'ap kenbe pwomès li pou tout tan tout tan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 16, text = "Se kontra li te fè ak Abraram lan, sèman li te fè bay Izarak la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 17, text = "Sa li te pwomèt Abraram lan, li fè l' tounen yon lwa pou pitit Jakòb yo, yon kontra ak pèp Izrayèl la pou tout tan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 18, text = "Li te di: M'ap ba ou peyi Kanaran an pou pòsyon pa ou nan byen m' yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 19, text = "Lè sa a, pèp Bondye a pa t' anpil. Yo te sèlman yon ti ponyen moun. Yo te tankou etranje toujou nan peyi a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 20, text = "Yo t'ap mache ale vini nan tout nasyon yo. Yo t'ap soti nan yon peyi ale nan yon lòt.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 21, text = "Men, li pa t' kite pesonn maltrete yo. Li te menm rive pini anpil wa poutèt yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 22, text = "Li te di: Piga nou manyen moun mwen chwazi yo. Piga nou fè pwofèt mwen yo anyen.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 23, text = "Nou tout ki rete sou latè, chante pou Seyè a! Chak jou, fè konnen jan li delivre nou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 24, text = "Fè nasyon yo konnen pouvwa li. Fè tout pèp yo konnen bèl bagay li fè yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 25, text = "Seyè a gen gwo pouvwa. Li merite pou yo fè lwanj li vre. Se pou tout moun pè l' pi plis pase lòt bondye yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 26, text = "Bondye lòt nasyon yo pa anyen, se pòtre yo ye. Men, se Seyè a ki fè syèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 27, text = "Devan li, se respè, se chapo ba. Gen pouvwa, gen kè kontan kote l' ye lakay li a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 28, text = "Nou tout pèp ki sou latè, fè lwanj Seyè a! Fè lwanj Seyè a pou pouvwa ak fòs li genyen!", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 29, text = "Fè lwanj Seyè a, paske li merite sa! Pote ofrann ba li anndan lakay li! Adore Bondye nan bèl kay ki apa pou li a!", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 30, text = "Nou tout ki sou latè, tranble devan li. Latè kanpe fèm, anyen pa ka brannen l'.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 31, text = "Se pou syèl la kontan, se pou latè a fè fèt. Mache di nan tout peyi yo: Se Seyè a ki sèl wa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 32, text = "Se pou lanmè a ansanm ak tou sa ki ladan l' pran fè bri sitèlman yo kontan. Se pou jaden yo ak tou sa ki ladan yo fè fèt.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 33, text = "Lè Seyè a parèt se pou tout pyebwa nan gwo rak yo rele sitèlman yo kontan. Paske l'ap vini pou l' jije tout moun ki sou latè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 34, text = "Lwanj pou Seyè a paske li bon. Li p'ap janm sispann renmen nou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 35, text = "Se pou nou di: Delivre nou non, Bondye delivrans nou! Fè nou soti nan tout peyi kote nou gaye yo. Sanble nou, pou nou ka di ou mèsi pou tout bagay ou menm sèl ka fè, pou nou ka kontan lè n'ap fè lwanj ou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 36, text = "Ann fè lwanj Seyè a, Bondye pèp Izrayèl la! Ann fè lwanj li depi tout tan ak pou tout tan. Epi tout pèp la pran reponn: -Wi, se vre! Lwanj pou Seyè a!", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 37, text = "Lèfini, David kite Asaf ak moun Levi menm fanmi avè l' yo devan Bwat Kontra Seyè a pou yo toujou reskonsab tout sèvis ki pou fèt kote yo te mete Bwat Kontra a. Yo te gen pou fè sèvis yo la chak jou san rete.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 38, text = "Obèd-Edon ak swasantwit lòt moun nan fanmi li t'ap ede yo nan travay yo. Osa ak Obèd-Edon, pitit gason Jeditoun lan, te reskonsab pòtay yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 39, text = "Men David kite Zadòk, prèt la, ak moun Levi menm fanmi avè l' yo ki te prèt tou devan Tant Seyè a, nan kote yo te mete apa pou Seyè a lavil Gabawon.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 40, text = "Chak maten, chak aswè, se yo ki pou boule bèt yo ofri bay Seyè a nèt sou lotèl ki fèt pou sa a, dapre sa ki ekri nan lalwa Seyè a te bay pèp Izrayèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 41, text = "Te gen avèk yo tou Eyman, Jedoutoun ansanm ak lòt moun yo te chwazi tout espre pou chante: Lwanj pou Seyè a paske li p'ap janm sispann renmen nou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 42, text = "Eyman ak Jedoutoun te gen twonpèt, senbal ki fè gwo bri yo ak lòt enstriman mizik pou yo jwe antan yo t'ap chante fè lwanj pou Bondye. Manm fanmi Jedoutoun yo te reskonsab veye pòtay yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 16, verseNumber = 43, text = "Apre sa, tout pèp la tounen lakay yo. David tounen lakay li tou pou l' beni fanmi pa l' tou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 1, text = "Wa David te byen chita nan palè li. Yon jou li fè rele pwofèt Natan, li di l' konsa: -Gade! Mwen rete nan yon kay bati ak bwa sèd, men Bwat Kontra Seyè a se anba yon kay twal li ye.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 2, text = "Natan reponn li: -Tou sa ou gen lide fè, ou mèt fè l' paske Seyè a kanpe la avèk ou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 3, text = "Men, menm jou lannwit sa a, Bondye pale ak Natan. Li di l' konsa:", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 4, text = "-Ale di David, sèvitè m' lan, men sa mwen menm Seyè a, mwen voye di l': Se pa ou menm ki pral bati yon tanp pou m' rete.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 5, text = "Depi jou mwen te fè moun pèp Izrayèl yo soti kite peyi Lejip rive jòdi a, mwen pa janm rete nan yon kay. Tout kote m' pase, se anba yon tant twal mwen toujou ye.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 6, text = "Nan tout deplasman mwen ansanm ak moun Izrayèl yo, mwen pa janm mande yonn nan chèf mwen te chwazi pou gouvènen pèp mwen an poukisa yo pa bati yon kay ak bwa sèd pou mwen.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 7, text = "Koulye a, men sa w'a di David, sèvitè m' lan: Men sa Seyè ki gen tout pouvwa a voye di ou: Se mwen menm ki te pran ou dèyè mouton ou t'ap gade nan savann yo, mwen mete ou chèf pèp Izrayèl la, pèp mwen an.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 8, text = "Kote ou pase, mwen te kanpe la avè ou. Mwen kraze tout lènmi ou yo devan ou. Mwen pral fè yo nonmen non ou tankou y'ap nonmen non pi gwo chèf ki sou latè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 9, text = "Lèfini, mwen pare yon kote pou pèp Izrayèl mwen an. Mwen pral tabli yo la pou yo ka viv san yo pa bezwen pè anyen ankò. Mechan p'ap vin maltrete yo ankò jan yo te konn fè l' anvan an,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 10, text = "lè mwen te mete jij chèf yo pou gouvènen pèp Izrayèl mwen an. M'ap delivre ou anba men tout lènmi ou yo. Mwen te fè ou konnen m'ap ba ou pitit ak pitit pitit.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 11, text = "Lè lè a va rive pou ou mouri, lè y'a antere ou, m'ap pran yonn nan pitit ou yo, m'ap mete l' wa nan plas ou. M'ap fè gouvènman l' lan kanpe fèm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 12, text = "Se li menm ki va bati yon tanp pou mwen, m'ap fè gouvènman l' lan kanpe fèm pou tout tan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 13, text = "M'ap yon papa pou li. Li menm l'ap yon pitit pou mwen. Mwen p'ap lage l' jan mwen te lage moun ki te wa anvan ou lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 14, text = "M'ap mete l' chèf lakay mwen ak nan gouvènman mwen an pou tout tan. M'ap fè gouvènman fanmi li an kanpe fèm pou tout tan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 15, text = "Natan rakonte David tou sa Bondye te fè l' konnen nan vizyon an.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 16, text = "Aprè sa, wa David ale nan Tanp lan, li chita devan Seyè a, li di l' konsa: -Seyè Bondye sèl Mèt la, kisa mwen ye? Kisa fanmi mwen ye pou ou te fè tout sa ou deja fè pou nou?", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 17, text = "Men, ou wè sa pa kont toujou, Bondye sèl Mèt la! Kifè koulye a w'ap fè konnen sa ki pral rive fanmi mwen denmen nan lanne k'ap vini yo. Ou trete m' tankou yon grannèg, Seyè sèl Mèt la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 18, text = "Kisa mwen menm David, mwen ka di ou, Seyè, apre sa pou bèl bagay ou fè pou mwen yo? Ou konnen ki moun mwen ye, mwen menm k'ap sèvi ou la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 19, text = "Se paske ou te fè pwomès la, paske ou te vle l' konsa, Seyè, kifè ou te fè tout bèl bagay sa yo pou ou te fè m' konnen yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 20, text = "Seyè, Bondye mwen, pa gen tankou ou. Pa gen lòt Bondye pase ou menm! Yo te toujou di nou sa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 21, text = "Pa gen lòt nasyon sou latè tankou pèp Izrayèl la. Se ou menm ki delivre yo pou yo te ka tounen yon pèp ki rele ou pa ou. Se pou yo ase ou fè sa! Toupatou sou latè y'ap nonmen non ou pou gwo mirak ak bèl bagay ou fè pou yo. Ou mete lòt nasyon deyò pou fè plas pou pèp ou a, pèp ou te delivre anba pouvwa pèp peyi Lejip la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 22, text = "Ou fè pèp Izrayèl la tounen pèp pa ou pou tout tan, ou menm ou tounen Bondye yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 23, text = "Koulye a, Seyè, Bondye, se pou ou kenbe pwomès ou te fè sèvitè ou la ansanm ak fanmi li an. Se pou ou fè sa ou di w'ap fè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 24, text = "Kenbe pwomès ou pou tout moun rekonèt jan ou gen pouvwa, pou yo di: Se Seyè ki gen tout pouvwa a ki Bondye pèp Izrayèl la vre. Se yon Bondye pou pèp Izrayèl la. Konsa, gouvènman ki nan men fanmi David, sèvitè ou la, va kanpe fèm pou tout tan devan ou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 25, text = "Se ou menm, Bondye mwen, ki te fè m' konnen tou sa. Ou te di m', mwen menm sèvitè ou la, w'ap ban mwen yon fanmi, lèfini w'ap fè baton gouvènman an toujou rete nan men fanmi mwen. Se poutèt sa mwen gen kouraj fè lapriyè sa a nan pye ou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 26, text = "Koulye a, Seyè, se ou ki Bondye, se ou ki pwomèt sèvitè ou la bèl bagay sa yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 17, verseNumber = 27, text = "Tanpri, beni tout fanmi mwen apre mwen, pou yo ka toujou anba pwoteksyon ou. Wi, Seyè, se ou ki bay benediksyon. Se pou ou toujou voye benediksyon ou sou fanmi mwen.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 18, verseNumber = 1, text = "Apre sa, David atake moun Filisti yo ankò. Li bat yo byen bat. Se konsa li pran lavil Gat ak tout ti bouk ki te sou lòd li yo, nan men moun Filisti yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 18, verseNumber = 2, text = "Lèfini, li bat moun peyi Moab yo. Moun Moab yo soumèt devan David. Li fè yo peye taks ba li chak lè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 18, verseNumber = 3, text = "Apre sa, li bat Adadezè, wa peyi Zoba a, ki t'ap mache pran zòn ki sou anwo larivyè Lefrat la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 18, verseNumber = 4, text = "David pran mil (1.000) cha lagè, sèt mil (7.000) kavalye nan lame wa Adadezè a, li fè yo prizonye ansanm ak venmil (20.000) sòlda ki t'ap mache apye. Lè li fin wete kont chwal pou san (100) cha lagè, li fè koupe jarèt tout rès chwal yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 18, verseNumber = 5, text = "Moun Siri lavil Damas yo voye yon lame pou pote Adadezè, wa peyi Zoba a, konkou. David atake yo, li bat yo tou. Li touye venndemil (22.000) sòlda.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 18, verseNumber = 6, text = "Apre sa, David mete moun pa l' pou gouvènen peyi Damas la. Moun Siri yo soumèt devan li. Li fè yo peye taks chak lè. Se konsa Seyè a te fè David genyen tout batay kote l' pase.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 18, verseNumber = 7, text = "David sezi tout gwo plak pwotèj an lò chèf lame wa Adadezè yo, li pote yo lavil Jerizalèm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 18, verseNumber = 8, text = "Li pran yon gwo kantite kwiv li te jwenn lavil Tiba ak lavil Koun ki te pou Adadezè. Se ak kwiv sa yo Salomon te fè gwo basen lan, poto won yo ak lòt veso an kwiv pou Tanp lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 18, verseNumber = 9, text = "Lè Towou, wa lavil Amat la, tande jan David te kraze tout lame Adadezè a,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 18, verseNumber = 10, text = "li voye pitit li, Adouram al wè David pou di l' bonjou, epi pou fe l' konpliman deske li te bat Adadezè, paske Towou te toutan ap fè lagè ak Adadezè. Adouram te pote kado fèt an lò, an ajan ak an kwiv bay David.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 18, verseNumber = 11, text = "Wa David pran tout bagay sa yo, li mete yo apa pou sèvis Seyè a, ansanm ak tout lò ak tout ajan li te pran lakay moun lòt nasyon li te fè soumèt devan li, ki vle di moun peyi Edon, moun peyi Moab, moun peyi Amon, moun peyi Filisti ak moun peyi Amalèk.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 18, verseNumber = 12, text = "Apre sa, Abichayi, pitit gason Sewouja a, touye dizwitmil (18.000) moun peyi Edon nan Fon Sèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 18, verseNumber = 13, text = "Li mete kèk ganizon sòlda nan teritwa Edon an. Tout moun Edon yo soumèt devan David. Se konsa, Seyè a te fè David genyen tout batay kote l' pase.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 18, verseNumber = 14, text = "David t'ap gouvènen tout pèp Izrayèl la. Li te fè tout moun jistis san patipri. Li te fè tout afè l' dwat.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 18, verseNumber = 15, text = "Joab, pitit gason Sewouya a, te kòmandan chèf lame a. Jozafa, pitit gason Akiloud la, te reskonsab achiv yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 18, verseNumber = 16, text = "Zadòk, pitit gason Akitoub, ak Akimelèk, pitit gason Abyata a, te prèt. Chaoucha te sekretè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 18, verseNumber = 17, text = "Benaja, pitit gason Jeojada a, te chèf keretyen yo ak pelesyen yo ki te gad pèsonèl wa a. Pitit gason David yo menm te gwo chèf apre wa a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 1, text = "Apre sa, Nakach, wa lavil Amon, mouri. Se pitit gason li ki moute wa nan plas li.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 2, text = "David di: -Se pou m' aji byen ak Anoun, pitit Nakach la, paske papa l' te boule byen avè m'. Se konsa, David voye mesaje al di Anoun jan sa te fè l' lapenn lè l' pran nouvèl lanmò papa l'. Mesaje David yo rive lakay Anoun nan peyi moun Amon yo pou konsole l'.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 3, text = "Men, chèf moun Amon yo di Anoun konsa: -Pa konprann se sèlman pou lanmò papa ou la kifè David voye mesaje sa yo bò kote ou pou konsole ou. Wete sa nan tèt ou. Li voye yo isit la pou yo wè jan lavil la ye, pou yo gade byen sa k'ap pase nan lavil la. Konsa, pita li ka vin pran lavil la nan men nou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 4, text = "Sa Anoun fè lè sa a, li pran moun David te voye yo, li raze tout yon bò nan bab yo, li koupe anba rad yo ra dèyè yo, li voye yo tounen.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 5, text = "Mesye yo te wont anpil pou yo te tounen lakay yo konsa. Lè David vin konn sa ki te rive yo, li voye di yo rete lavil Jeriko, y'a tounen lakay yo lè bab yo va pouse ankò.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 6, text = "Wa Anoun ak moun Amon yo vin konprann yo te fè David fache. Yo pran mil pyès ajan, yo voye chache sòlda, cha lagè, ak kavalye kay moun Aram yo lavil Narayim, lavil Maka ak lavil Zoba pou vin goumen pou yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 7, text = "Se konsa yo lwe sèvis tranndemil (32.000) cha lagè ki vin kanpe devan lavil Medeba ansanm ak wa lavil Maka a ak tout lame li a. Moun peyi Amon yo kite lavil yo, yo reyini ansanm pou pare pou batay la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 8, text = "David vin konnen sa. Li voye Joab ak tout lame vanyan sòlda li yo al kontre yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 9, text = "Moun Amon yo soti, y' al pran pozisyon devan pòtay lavil la. Wa ki te vin ede yo bò pa yo pran pozisyon nan plenn lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 10, text = "Joab te wè lame lènmi yo te ka atake l' ni sou devan, ni sou dèyè. Sa l' fè, li chwazi pi bon sòlda nan lame pèp Izrayèl la, li mete yo an pozisyon devan lame moun Aram yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 11, text = "Lèfini, li mete Abichayi, frè l' la, alatèt rès lame a. Li fè yo pran pozisyon devan moun Amon yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 12, text = "Joab di Abichayi konsa: -Si nou wè moun Aram yo soti pou yo bat mwen, w'a vin ede m'. Konsa tou, si mwen wè moun Amon yo vle pi fò pase ou, m'a vin ede ou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 13, text = "Mete gason sou nou. Kouraj! Nou pral goumen rèd mare pou pèp nou an ak pou lavil Bondye nou an. Bondye va fè sa li vle li menm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 14, text = "Joab ak sòlda ki te avè l' yo mache sou moun Aram yo. Moun Aram yo kouri pou li.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 15, text = "Lè moun peyi Amon yo wè moun Aram yo kouri ale, yo kouri tou pou Abichayi, frè Joab la, yo antre nan lavil la. Lè sa a, Joab tounen tounen l' lavil Jerizalèm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 16, text = "Lè moun Aram yo wè moun Izrayèl yo te bat yo, yo voye yon mesaj bay moun Aram ki te lòt bò larivyè Lefrat la, pou yo pare vin goumen pou yo. Yo reyini lavil Elam. Se Chofak, chèf lame Adadezè a, ki te alatèt yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 17, text = "Lè David vin konn sa, li sanble tout lame pèp Izrayèl la, li janbe lòt bò larivyè Jouden, li mache sou yo, li pran pozisyon devan yo. David ranje sòlda li yo pou li goumen ak moun Aram yo. Epi batay la konmanse.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 18, text = "Moun Izrayèl yo fè moun Aram yo kouri met deyò. David ak sòlda li yo touye sòlda ki te sou sètmil (7.000) cha lagè ak karantmil (40.000) sòlda ki te apye. Yo touye Chofak, chèf lame lènmi an.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 19, verseNumber = 19, text = "Lè moun ki te avek Adadezè yo wè jan moun Izrayèl yo te bat yo, yo fè lapè ak David. Yo soumèt devan li. Se konsa, moun Aram yo pa t' vle vin pote moun Amon yo sekou ankò.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 20, verseNumber = 1, text = "Nan prentan apre sa, nan epòk wa yo konn soti al fè lagè, Joab pati ak pifò sòlda lame pèp Izrayèl la. Yo ravaje peyi Amon an, yo sènen lavil Raba. David menm te rete lavil Jerizalèm. Joab pran lavil la, li kraze l'.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 20, verseNumber = 2, text = "Estati Milkòm, zidòl moun Amon yo, te gen yon gwo kouwòn fèt an lò sou tèt li. Kouwòn lan te peze swasannkenz liv, li te gen yon gwo pyè koute chè ladan l'. David pran kouwòn lò ki te sou tèt zidòl la, li mete l' sou tèt pa l'. Lèfini, se pa de bagay li pa pran nan lavil la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 20, verseNumber = 3, text = "Li pran moun ki te rete nan lavil la, li mete yo fè travay ak goyin, wou ak rach. Li fè menm bagay la tou nan tout lòt lavil peyi Amon an. Apre sa, David tounen lavil Jerizalèm ak tout moun li yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 20, verseNumber = 4, text = "Apre sa, lagè pete ankò ant moun Filisti yo ak moun pèp Izrayèl yo bò lavil Gezè. Lè sa a, Sibekayi, yon moun lavil Ousa, touye Sipayi, yon moun nan ras Arafa yo. Yo fè moun Filisti yo soumèt devan yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 20, verseNumber = 5, text = "Pandan yon lòt batay ak moun Filisti yo ankò, Elkanan, pitit gason Jayi, touye Lami, frè Golyat, yon moun lavil Gat. Frenn Lami an te gen yon manch menm gwosè ak yon gwo manch pilon.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 20, verseNumber = 6, text = "Vin gen yon lòt batay ankò lavil Gat. Lè sa a, te gen yon sòlda bèl wotè ki te gen sis dwèt nan chak men, sis zòtèy nan chak pye. Se te yonn nan ras moun Arafa yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 20, verseNumber = 7, text = "Li t'ap pase moun pèp Izrayèl yo nan betiz. Jonatan, pitit gason Chimeya, frè David la, touye l'.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 20, verseNumber = 8, text = "Kat sòlda peyi Filisti sa yo te soti nan ras moun Arafa yo, nan lavil Gat. David ak sòlda li yo touye yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 1, text = "Yon jou, Satan move sou pèp Izrayèl la, li pouse David al konte konbe moun ki nan pèp Izrayèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 2, text = "Wa a pale ak Joab ansanm ak lòt chèf yo, li di yo konsa: -Ale nan tout branch fanmi Izrayèl yo, depi lavil Bètcheba nan sid jouk lavil Dann nan nò. Konte dènye moun ki nan pèp la. Lèfini, fè m' yon rapò pou m' ka konnen konbe moun ki gen nan peyi a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 3, text = "Men Joab di wa a konsa: -Monwa, mwen mande Seyè a pou li fè pèp Izrayèl la vin san fwa pi plis pase jan li ye koulye a. Lèfini, monwa, ou konnen yo tout la ap sèvi ou. Men poukisa, monwa, ou vle fè sa? Poukisa ou vle pòte pèp Izrayèl la fè sa ki mal?", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 4, text = "Men, wa a pa t' soti pou li chanje lòd li te bay la. Konsa, Joab pati, li vwayaje nan tout peyi a. Apre sa, li tounen lavil Jerizalèm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 5, text = "Joab renmèt wa a rapò ki bay kantite moun ki te gen antou nan tout peyi a. Se konsa yo te jwenn yon milyon sanmil (1.100.000) gason ki konn sèvi ak nepe nan peyi Izrayèl la ak katsanswasanndimil (470.000) nan peyi Jida a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 6, text = "Men Joab pa t' konte moun ni nan branch fanmi Levi a, ni nan branch fanmi Benjamen an, paske lòd wa a te bay la pa t' antre nan santiman l' menm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 7, text = "Men, sa David te fè a pa t' fè Bondye plezi. Bondye pini pèp Izrayèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 8, text = "Lè sa a, David di Bondye: -Sa m' fè la a, se yon gwo peche. Koulye a, tanpri, padonnen m'. Pa bliye se sèvitè ou mwen ye. Mwen te aji tankou moun fou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 9, text = "Seyè a pale ak pwofèt Gad, konseye David la, li di l' konsa:", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 10, text = "-Ale pale ak David. W'a di l' men mesaj Seyè a voye ba ou. Li mete twa chatiman devan ou. Ou menm, w'a chwazi yonn ladan yo. Sa w'a chwazi a, se sa l'a fè ou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 11, text = "Se konsa Gad al jwenn David lakay li, li di l' konsa: -Men sa Seyè a voye di ou: Kisa ou vle?", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 12, text = "Twa lanne grangou nan tout peyi a, twa mwa ap kouri devan lènmi k'ap pousib ou ak sòlda yo, osinon twa jou ap sibi chatiman Seyè a ak yon epidemi nan tout peyi a, pou zanj Seyè a menm ap mache touye moun nan tout peyi Izrayèl la? Al kalkile sou sa pou fe m' konnen ki repons pou m' pote bay moun ki voye m' lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 13, text = "David reponn: -M' nan gwo tèt chaje! Men, m' pa vle tonbe anba men lèzòm menm! Pito se Seyè a ki pini m', paske li gen bon kè!", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 14, text = "Se konsa, Seyè a voye yon epidemi sou pèp Izrayèl la. Li touye swasanndimil (70.000) moun nan pèp Izrayèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 15, text = "Seyè a te voye zanj li sou lavil Jerizalèm pou detwi l'. Lè zanj lan konmanse fè travay li, Seyè a wè sa, li fè lide sispann chatiman an. Li di zanj ki t'ap touye moun yo: -Sispann! Kenbe men ou! Lè sa a, zanj lan te gen tan toupre glasi Onan an, moun lavil Jebis la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 16, text = "David voye je l', li wè zanj Seyè a kanpe nan lè a, san pye l' pa touche tè, bra l' lonje sou lavil Jerizalèm ak yon nepe nan men l'. Lè sa a, David ak chèf fanmi yo, rad sak yo sou yo, bese tèt yo jouk atè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 17, text = "David pale ak Seyè a, li di l' konsa: -Se mwen menm ki te mande pou yo konte moun yo. Se mwen menm ki antò. Se mwen menm ki fè sa ki mal. Kisa moun sa yo fè? Se mouton yo ye. Tanpri, Seyè, Bondye mwen, pa voye ankenn malè sou pèp la. Se mwen menm ansanm ak fanmi mwen pou ou ta pini.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 18, text = "Zanj Seyè a te bay pwofèt Gad lòd pou l' te al mande David pou l' moute lakay Onan, moun lavil Jebis la, bati yon lotèl pou Seyè a nan mitan glasi a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 19, text = "David koute sa Gad te di l' la, li moute lakay Onan jan Seyè a te ba li lòd la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 20, text = "Onan menm t'ap bat ble ansanm ak kat pitit gason l' yo ki te la avè l' sou glasi a. Lè yo wè zanj lan, pitit li yo kouri al kache.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 21, text = "Onan vire tèt li, li wè David ki t'ap vini. Li kite glasi a, li tonbe ajenou devan wa a, li bese tèt li jouk fwon li touche tè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 22, text = "David di Onan konsa: -Vann mwen anplasman glasi a pou m' bati yon lotèl pou Seyè a. Ban mwen li pou pri li vo. Konsa, epidemi k'ap fini ak pèp la va sispann.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 23, text = "Onan di David konsa: -Monwa, ou mèt pran l' pou fè sa ou vle avè l'. Men m'ap bay bèf sa yo pou ou boule nèt sou lotèl la. Men jouk bèf yo ak bwa kabwa yo pou fè dife, ak ble pou sèvi ofrann grenn jaden an. M'ap ba ou tout bagay sa yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 24, text = "Men wa David reponn Onan, li di l': -Non. Se achte m'ap achte. Se pou m' peye ou sa yo vo. M' pa ka ofri Seyè a sa ki pou ou. Mwen p'ap pran anyen ki pa koute m' lajan pou m' ofri bay Seyè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 25, text = "Se konsa David bay Onan swasant pyès lò pou anplasman glasi a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 26, text = "Lèfini, li bati yon lotèl pou Seyè a, li fè ofrann bèt boule pou Bondye ak ofrann pou di Bondye mèsi. Li lapriyè nan pye Seyè a. Seyè a reponn li, li voye dife soti nan syèl la pou boule ofrann ki sou lotèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 27, text = "Lè sa a, Seyè a bay zanj li a lòd pou li mete nepe li nan djenn li ankò.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 28, text = "Lè David wè Seyè a te reponn lapriyè li te fè nan pye l' sou glasi Onan, moun lavil Jebis la, li ofri bèt pou touye sou lotèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 29, text = "Men lè sa a, Tant Randevou Moyiz te fè moute pou Seyè a nan dezè a ansanm ak lotèl pou boule ofrann bèt yo te sou mòn Gabawon toujou, kote yo te mete apa pou Seyè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 21, verseNumber = 30, text = "Men, David pa t' ka ale la pou adore Seyè a, paske li te pè nepe zanj Seyè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 1, text = "Se konsa David te di: -Se la Tanp Bondye Seyè a ye, ansanm ak lotèl pou boule bèt yo ofri bay Bondye pou pèp Izrayèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 2, text = "David bay lòd pou tout moun lòt nasyon k'ap viv nan peyi Izrayèl la reyini. Li moute chantye kote pou taye wòch pou bati Tanp Bondye a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 3, text = "Li fè pare fè an kantite pou fè klou ak kranpon pou batan pòt yo. Pou kwiv la menm, moun pa ka kalkile kantite li te fè pare.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 4, text = "Pou bwa sèd, moun peyi Sidon ak moun lavil Tir te fè David jwenn sa an kantite.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 5, text = "David t'ap di nan kè l': Salomon, pitit gason m' lan, se yon timoun ki poko gen esperyans. Tanp li gen pou l' bati pou Seyè a, se li ki pou pi gwo, pi bèl pase dènye tanp, pou toupatou sou latè y'ap pale sou li. Se pou m' pare tout bagay kite pou li. Se konsa, anvan li mouri, David pare materyo an kantite kite la pou sa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 6, text = "Lèfini, li voye chache Salomon, pitit gason l' lan, li ba li lòd pou li bati Tanp Seyè a, Bondye pèp Izrayèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 7, text = "Li di l' konsa: -Pitit mwen, mwen te fè lide bati yon tanp pou Seyè a, Bondye mwen an.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 8, text = "Men Seyè a fè m' konnen mwen touye twòp moun, mwen fè anpil lagè. Se poutèt sa se pa mwen ki pral bati tanp lan pou li, paske mwen fè twòp san koule.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 9, text = "Men li di m' konsa: Ou pral gen yon pitit gason ki p'ap nan touye moun li menm. M'ap fè tout lènmi l' yo toupatou viv byen ak li tou. Se poutèt sa y'a rele l' Salomon. Sou rèy li, peyi Izrayèl la ap viv ak ke poze, san danje ni malè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 10, text = "Se li menm ki va bati yon tanp pou mwen. L'ap yon pitit pou mwen, mwen menm m'ap yon papa pou li. M'ap fè l' toujou gen yon moun nan fanmi l' wa pou gouvènen pèp Izrayèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 11, text = "Koulye a, pitit mwen, se pou Seyè a, Bondye w'ap sèvi a, toujou kanpe la avè ou pou ou ka rive bati Tanp lan pou li, jan li te pwomèt ou sa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 12, text = "Mwen mande Seyè a pou l' ba ou bon konprann ak anpil lespri, pou lè l'a mete ou chèf nan peyi Izrayèl la, ou ka toujou fè tou sa ki nan Lalwa Seyè a, Bondye ou la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 13, text = "Konsa, tout bagay va mache byen pou ou si ou veye kò ou pou ou mennen bak ou dapre lòd ak regleman Seyè a te bay Moyiz pou pèp Izrayèl la. Mete gason sou ou, kenbe fèm! Pa kite anyen fè ou pè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 14, text = "Gade! Mwen bay kò m' anpil traka pou m' pare tout bagay pou Tanp Seyè a: twamil twasan (3.300) tòn lò, tranntwamil (33.000) tòn ajan, ak yon gwo kantite kwiv ak fè moun pa ka kalkile. M' pare bwa ak wòch tou. Men, se pou ou fè pare toujou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 15, text = "Lèfini, w'ap jwenn anpil travayè, kantonye, moun pou taye wòch, chapant, ak anpil moun ki bòs nan tout kalite travay.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 16, text = "Pou lò, ajan, kwiv ak fè, ou gen sa an kantite. Konsa, mete men nan travay la! Mwen mande pou Seyè a toujou kanpe la avè ou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 17, text = "Apre sa, David mande tout chèf pèp Izrayèl yo pou yo ede Salomon, pitit gason l' lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 18, text = "Li di yo konsa: -Seyè a, Bondye nou an, te toujou la avèk nou. Li fè nou viv nan lapè ak tout moun toupatou. Li lage nan men mwen tout lòt moun ki rete nan peyi a, kifè tout peyi a soumèt nèt devan Seyè a ak devan pèp li a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 22, verseNumber = 19, text = "Koulye a, se pou nou pran desizyon chache fè volonte Seyè a, Bondye nou an, ak tout kè nou, ak tout nanm nou. Pare kò nou pou nou bati tanp Seyè a, Bondye nou an, pou nou ka mete Bwat Kontra Seyè a ak tout lòt bagay yo mete apa pou fè sèvis Seyè a ladan l'.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 1, text = "David te fin vye granmoun, li te fin viv kont li, lè li mete Salomon, pitit li a, wa sou pèp Izrayèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 2, text = "Li reyini tout chèf pèp Izrayèl yo, tout prèt yo ak tout moun Levi yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 3, text = "Li fè konte tout moun Levi yo, depi sa ki gen trantan pou pi piti rive sou sa ki pi gran yo. Antou yo jwenn trantwimil (38.000) gason.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 4, text = "David mete vennkatmil (24.000) pou dirije travay tanp lan, simil (6000) pou ekri tou sa k'ap pase ak pou rann jistis,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 5, text = "katmil (4000) pou fè pòs nan pòtay la ak katmil (4000) pou fè lwanj Seyè a ak enstriman mizik David te fè fè pou sa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 6, text = "David separe moun Levi yo fè twa gwoup dapre branch fanmi pitit gason Levi yo: Gèchon, Keyat ak Merari.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 7, text = "Gèchon te gen de pitit gason: Layedan ak Chimèyi.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 8, text = "Layedan te fè twa pitit gason: Yekiyèl, pi gran an, Zetam ak Joèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 9, text = "Chimeyi te fè twa pitit gason tou: Chelomit, Aziyèl ak Aran. Se yo ki te chèf fanmi moun Layedan yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 10, text = "Chimeyi te gen kat lòt pitit gason: Jaka, Ziza, Jeouch ak Berya.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 11, text = "Se Jaka ki te pi gran, Ziza te dezyèm pitit la. Jeouch ak Berya pa t' gen anpil pitit. Se konsa yo mete yo ansanm, yo pase pou yon sèl branch fanmi.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 12, text = "Keyat te gen kat pitit: Amram, Jizeya, Ebwon ak Ouzyèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 13, text = "Amram te gen de pitit gason: Arawon ak Moyiz. Bondye te mete Arawon ak pitit li yo apa pou yo okipe pyès ki apa nèt pou Bondye a, pou boule lansan devan Seyè a, pou yo sèvi l', pou yo beni pèp la nan non li. Se te travay pa yo sa pou tout tan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 14, text = "Moyiz te moun Bondye a menm. Pitit li yo te fè pati branch fanmi Levi a tou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 15, text = "Moyiz te gen de pitit gason: Gèchòm ak Elyezè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 16, text = "Premye pitit Gèchòm lan te rele Chebwèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 17, text = "Elyezè li menm te gen Rekabya pou premye pitit. Li pa t' fè lòt pitit gason ankò. Men Rekabya te fè anpil pitit.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 18, text = "Premye pitit Jizeya a te rele Chelomit.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 19, text = "Men pitit Ebwon yo: Premye a te rele Jerija, dezyèm lan Amarya, twazyèm lan Jakazyèl, katriyèm lan Jekameam.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 20, text = "Men pitit Ouzyèl yo: Miche, premye a ak Jikija, dezyèm lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 21, text = "Merari te gen de pitit gason: Makli ak Mouchi. Makli te gen de pitit gason: Eleaza ak Kich.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 22, text = "Eleaza mouri san kite pitit gason. Pitit fi ase li te genyen. Yo marye ak kouzen yo, pitit gason Kich yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 23, text = "Mouchi te gen twa pitit gason: Makli, Edè ak Jerimòt.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 24, text = "Se tout moun nan ras Levi yo sa, dapre fanmi yo, ki te gen non yo kouche nan rejis tankou chèf fanmi. Yo chak te gen travay pa yo nan sèvis kay Seyè a, depi sa ki gen ventan pou pi piti rive sou pi gran yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 25, text = "David te di: -Seyè a, Bondye pèp Izrayèl la, te fè pèp li a viv ak kè poze. Li menm, Seyè a, l'ap toujou rete lavil Jerizalèm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 26, text = "Konsa, moun Levi yo p'ap nan pote Tant Randevou Seyè a ankò ansanm ak tout bagay yo bezwen pou fè sèvis pou li ankò.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 27, text = "Se konsa, dapre dènye pawòl sa yo David te di lè sa a, yo enskri tout moun Levi yo, depi sa ki gen ventan pou pi piti rive sou pi gran yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 28, text = "Travay yo se ede prèt yo, pitit Arawon yo, nan sèvis y'ap fè nan Tanp Seyè a. Se yo ki pou okipe lakou yo ak tout pyès nan Tanp lan. Se yo ki pou veye pou tout bagay rete nan kondisyon pou fè sèvis Bondye a. Se yo ki reskonsab tout lòt sèvis nan Tanp lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 29, text = "Yo te reskonsab pen yo te ofri bay Bondye yo, farin frans yo sèvi pou fè ofrann yo, pen san ledven yo, ofrann farin melanje ak lwil yo. Se yo ki te reskonsab peze ak mezire ofrann nan Tanp lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 30, text = "Lèfini, se pou yo la nan Tanp lan chak jou, nan maten ak nan aswè, pou di Bondye mèsi, pou fè lwanj pou li.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 31, text = "Se pou yo la tou lè y'ap fè ofrann pou yo boule nèt pou Seyè a jou repo yo, premye jou chak mwa yo, ak pou lòt jou fèt yo. Te gen regleman ki te bay travay moun Levi yo gen pou fè ak kantite moun ki pou fè chak travay. Se te reskonsablite yo pou yo te toujou ap sèvi Seyè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 23, verseNumber = 32, text = "Se yo menm tou ki te reskonsab okipe Tant Randevou a, ak kote yo mete apa pou Seyè a, ak prèt yo, fanmi yo ki soti nan branch fanmi Arawon an, lè y'ap sèvi nan Tanp lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 1, text = "Men moun ki te soti nan branch fanmi Arawon an dapre travay yo. Arawon te gen kat pitit gason: Nadab, Abiyou, Eleaza ak Itama.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 2, text = "Men Nadab ak Abiyou mouri anvan papa yo, san kite pitit gason. Konsa, se Eleaza ak Itama ki vin prèt apre Arawon.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 3, text = "Avèk konkou Zadòk, moun fanmi Eleaza a, ak Akimelèk, moun fanmi Itama a, wa David separe moun fanmi Arawon yo an gwoup. Chak gwoup te gen travay pa yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 4, text = "Men, lè yo jwenn te gen plis gason chèf fanmi nan moun Eleaza yo pase nan moun Itama yo, yo òganize sèz gwoup nan moun Eleaza yo ak wit gwoup nan moun Itama yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 5, text = "Nan tou de fanmi yo te gen moun ki te chèf nan Tanp lan ak chèf pou fè sèvis Bondye. Chak moun te gen tou pa yo. Yo te fè yo piye pou yo te ka konnen tou chak moun.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 6, text = "Se konsa, Chemaja, pitit Netaneyèl, yonn nan moun Levi yo, ki te sekretè, te kouche non yo nan rejis devan wa a, devan chèf yo, devan Zadòk, prèt la, devan Akimelèk, pitit Abyata, ak devan tout chèf fanmi prèt yo ak moun Levi yo. Yo piye yonn apre lòt, de moun Eleaza pou chak yon moun Itama.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 7, text = "Men nan ki lòd vennkat gwoup yo te soti lè yo fin piye: Jeoyarib soti premye, Jedaja dezyèm,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 8, text = "Arim twazyèm, Seorim katriyèm,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 9, text = "Malkija senkyèm, Mijamen sizyèm,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 10, text = "Akòz setyèm, Abija wityèm,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 11, text = "Jezwa nevyèm, Chekanya dizyèm,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 12, text = "Elyakib onzyèm, Yakim douzyèm,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 13, text = "Oupa trèzyèm, Jekebeab katòzyèm,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 14, text = "Bilga kenzyèm, Imè sèzyèm,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 15, text = "Ezi disetyèm, Apizèz dizwityèm,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 16, text = "Petaja diznevyèm, Ezekyèl ventyèm,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 17, text = "Jakin venteyenyèm, Gamoul venndezyèm,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 18, text = "Delaya venntwazyèm, Mazya vennkatriyèm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 19, text = "Se konsa yo te enskri non moun sa yo nan jan pou yo te al nan Tanp lan pou fè travay yo yonn apre lòt, jan Arawon zansèt yo te mete l' pou yo fè l' la, dapre lòd Seyè a, Bondye pèp Izrayèl la, te bay.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 20, text = "Men non lòt chèf fanmi ki soti nan fanmi Levi a: Se te Choubayèl nan fanmi Amran, Jedeya nan fanmi Choubayèl,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 21, text = "Ichiya nan fanmi Rekabya. Se li ki te pi gran.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 22, text = "Te gen Chelomòt nan fanmi Jizeya, Jaat nan fanmi Chelomòt.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 23, text = "Nan fanmi Ebwon an te gen Jerija, pi gran an, Amarya, dezyèm lan, Jaziyèl, twazyèm lan ak Jekameam, katriyèm lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 24, text = "Te gen tou Miche, pitit gason Ouzyèl, Chami, pitit gason Miche.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 25, text = "Jikija, frè Miche a, Zakari, pitit gason Jikija,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 26, text = "Makli ak Mouchi, pitit gason Merari, pitit gason Jazya yo, ki te pitit Merari.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 27, text = "Nan fanmi Merari a, Jazya, pitit li, te gen twa pitit gason: Choam, Zakou ak Ibri.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 28, text = "Makli te gen de pitit gason: Eleaza ki pa t' gen pitit gason,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 29, text = "ak Kich ki te papa Jerakmeyèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 30, text = "Mouchi te gen twa gason: Makli, Edè ak Jerimòt. Se tout fanmi Levi yo sa dapre non zansèt yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 24, verseNumber = 31, text = "Tankou moun fanmi Arawon yo, yo menm tou, yo piye devan wa David, devan Zadòk ak Akimelèk, devan chèf fanmi prèt yo ak moun Levi yo, pou yo separe travay la bay chak moun pa yo, depi sou fanmi chèf yo rive sou fanmi pi piti ladan yo, san patipri.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 1, text = "Apre sa, wa David ak chèf moun Levi ki reskonsab sèvis nan Tanp lan te chwazi branch fanmi Asaf, branch fanmi Eyman ak branch fanmi Jedoutoun pou ba yo travay pa yo. Se yo ki pou bay mesaj Bondye yo, antan y'ap jwe gita, bandjo ak senbal. Men lis moun yo te chwazi yo ak travay yo chak:", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 2, text = "Asaf te gen kat pitit: Zakou, Jozèf, Netama ak Acharela. Yo te sou zòd Asaf. Se li ki te konn fè konnen mesaj Bondye yo chak lè wa a mande l' pou l' fè l'.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 3, text = "Jedoutoun te gen sis pitit: Gedalya, Zeri, Izayi, Chimèy, Asabya ak Matatya. Yo te sou zòd Jedoutoun, papa yo. Se yo ki te konn fè konnen mesaj Bondye yo antan y'ap jwe gita, pou fè lwanj Bondye, pou di l' mèsi.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 4, text = "Eyman te gen katòz pitit: Boukija, Matanya, Ouzyèl, Sebwèl, Jerimòt, Ananya, Anani, Elyata, Gidalti, Womanti-Ezè, Josbekacha, Maloti, Oti ak Maziòt.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 5, text = "Bondye te bay Eyman, pwofèt wa a, katòz pitit gason sa yo ak twa pitit fi, dapre pwomès li te fè l' pou l' te ba li anpil pouvwa. Lè yo t'ap fè konnen mesaj Bondye yo, se yo ki te pou kònen twonpèt yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 6, text = "Se Eyman, papa yo, ki t'ap dirije yo lè y'ap chante nan sèvis y'ap fè nan Tanp Bondye a, antan y'ap jwe gita, bandjo ak senbal. Asaf, Jedoutoun ak Eyman te sou zòd wa a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 7, text = "Sa te fè antou desankatrevenwit (288) mizisyen ki te fò nan fè mizik, ansanm ak tout lòt moun Levi parèy yo ki te aprann chante pou Seyè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 8, text = "Yo fè tout moun piye, gran kou piti, ni sa ki te fò nan fè mizik, ni sa ki te fèk konmanse aprann, pou yo te ka konnen lè pou yo fè travay yo nan sèvis la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 9, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 10, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 11, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 12, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 13, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 14, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 15, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 16, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 17, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 18, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 19, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 20, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 21, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 22, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 23, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 24, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 25, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 26, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 27, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 28, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 29, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 30, text = "-(We vèsè 31)", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 25, verseNumber = 31, text = "Desankatrevenwit (288) mesye sa yo te separe chak fanmi apa. Sa te fè vennkat gwoup. Chak gwoup te gen douz moun. Nan chak gwoup te gen yon chèf ak pitit gason l' yo ansanm ak frè l' yo. Men nan ki lòd yo te soti apre yo fin piye a. Premye a te Jozèf nan fanmi Asaf la, dezyèm lan Gedalya, twazyèm lan Zakou, katriyèm lan Jisri, senkyèm lan Netanya, sizyèm lan Boukya, setyèm lan Acharela, wityèm lan Izayi, nevyèm lan Matanya, dizyèm lan Chimeyi, onzyèm lan Azareyèl, douzyèm lan Achabya, trèzyèm lan Choubayèl, katòzyèm lan Matatya, kenzyèm lan Jerimòt, sèzyèm lan Ananya, disetyèm lan Josbekacha, dizwityèm lan Anani, diznevyèm lan Maloti, ventyèm lan Elyata, venteyenyèm lan Oti, venndezyèm lan Gidalti, venntwazyèm lan Maziòt, vennkatryèm lan Womanti-Ezè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 1, text = "Men jan yo te separe travay la pou moun Levi ki t'ap sèvi tankou gad nan pòtay Tanp lan. Nan branch fanmi Kore a, te gen Mechelemya, pitit gason Kore a ki te yon pitit Ebyasaf.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 2, text = "Mechelemya te gen sèt pitit gason: Zakari pi gran an, Jedyayèl dezyèm lan, Zebadya twazyèm lan, Jatniyèl katriyèm lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 3, text = "Elam senkyèm lan, Joanan sizyèm lan ak Elioenayi setyèm lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 4, text = "Te gen Obèd-Edon tou. Bondye te beni l', li te ba li wit pitit gason: Chenaja premye a, Jeozabad dezyèm lan, Joa twazyèm lan, Saka katriyèm lan, Netaneyèl senkyèm lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 5, text = "Amiyèl sizyèm lan, Isaka setyèm lan ak Peoultayi wityèm lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 6, text = "Chemaja, premye pitit Obèd-Edon an, te gen sis pitit gason: Se yo ki te chèf nan branch fanmi yo paske yo te vanyan sòlda ak anpil ladrès.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 7, text = "Men non pitit Chemaja yo: Otni, Refayèl, Obèd, Elzabad, Eliyou ak Semakya. De dènye yo te vanyan sòlda.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 8, text = "Se tout fanmi Obèd-Edon an sa ansanm ak pitit yo ak frè yo. Yo tout te vanyan sòlda ak anpil ladrès pou fè travay yo. Te gen swasannde moun antou nan fanmi Obèd-Edon an.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 9, text = "Nan fanmi Mechelemya a, te gen antou dizwit gason, tout vanyan sòlda.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 10, text = "Nan branch fanmi Merari a te gen Oza ki te gen kat pitit gason: Se te Chimri ki te chèf fanmi an. Se pa li ki te premye pitit gason, men se papa l' ki te mete l' chèf fanmi an.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 11, text = "Ilkija dezyèm lan, Tebalya twazyèm lan, Zakari katriyèm lan. Sa te fè antou trèz frè ak pitit gason nan fanmi Oza a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 12, text = "Travay gwoup moun sa yo se fè pòs nan pòtay Tanp lan. Yo te bay chak gwoup travay pa yo nan sèvis Tanp lan, tankou yo te fè l' pou lòt moun Levi yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 13, text = "Chak fanmi, gwo kou piti, piye pou yo konnen nan ki pòtay y'ap fè travay yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 14, text = "Chelemya soti pou pòtay ki bay sou solèy leve a. Pòtay nò a soti pou Zakari, pitit gason l' lan, ki te konn bay moun bon konsèy.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 15, text = "Pòtay sid la soti pou Obèd-Edon. Pitit gason l' yo te gen depo yo sou kont yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 16, text = "Pòtay solèy kouche a ak pòtay Chalechèt ki bay sou chemen ki moute a te sou kont Choupim ak Oza. Chak faksyonnè, yonn apre lòt, te gen lè sèvis pa yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 17, text = "Chak jou, te gen sis gad pou pòtay bò solèy leve a, kat gad pou pòtay nò a, kat gad pou pòtay sid la ak de gad pou chak depo yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 18, text = "Pou pòsyon kay ki bay sou solèy kouche a, te gen kat gad pou wout la ak de gad pou pòsyon kay la menm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 19, text = "Men travay yo te bay moun fanmi Kore yo ak moun fanmi Merari yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 20, text = "Gen lòt moun Levi yo te mete reskonsab trezò Tanp lan ak depo kote yo mete tout bagay ki apa pou Bondye yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 21, text = "Layedan, yonn nan pitit Gèchon yo, te zansèt anpil fanmi. Yonn ladan yo te fanmi Jekiyèl yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 22, text = "Pitit Jekiyèl yo ak pitit frè l' yo, Zetam ak Joèl, te reskonsab trezò Tanp Seyè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 23, text = "Yo te bay pitit Amram yo, pitit Isa yo, pitit Ebwon yo ak pitit Ouzyèl yo travay pa yo tou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 24, text = "Chebwèl, yonn nan fanmi Gèchòm, pitit gason Moyiz la, te premye reskonsab trezò Tanp lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 25, text = "Sou bò Elyezè, tonton li, li te fanmi ak Rekabya, pitit Elyezè a, ki te papa Jezaja. Jezaja sa a te papa Joram, Joram te papa Zikri, Zikri te papa Chelomit.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 26, text = "Se Chelomit sa a ansanm ak fanmi l' yo ki te reskonsab depo tout bagay wa David, chèf fanmi yo, kòmandan rejiman mil sòlda yo, kòmandan divizyon san sòlda yo ak tout lòt gwo chèf nan lame a te mete apa pou Seyè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 27, text = "Nan bagay yo te pran nan lagè, yo te mete kèk ladan yo apa pou fè Tanp lan pi bèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 28, text = "Te gen bagay Samyèl, pwofèt la, wa Sayil, pitit gason Kich la, Abnè, pitit Nè a, ak Joab, pitit Sewouya a, te mete apa pou sèvis Bondye. Tou sa te sou kont Chelomit ak fanmi l' yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 29, text = "Nan branch fanmi Jizeya a, te gen Kenanya ak pitit gason l' yo ki te reskonsab travay ki fèt an deyò Tanp lan pou pèp Izrayèl la. Se yo ki te kenbe tout papye konsekan yo, epi ki te rann jijman nan tribinal.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 30, text = "Nan branch fanmi Ebwon an, te gen Asabya ak fanmi l' yo, antou milsètsan (1700) vanyan gason ki te reskonsab enspekte zòn peyi Izrayèl ki te sou bò solèy kouche larivyè Jouden an, pou wè si tout bagay ki gen rapò ak sèvis Seyè a ansanm ak zafè wa a t'ap mache byen.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 31, text = "David te gen karantan depi li te wa, lè yo mennen yon ankèt nan branch fanmi Ebwon an. Lè sa a, yo jwenn te gen anpil vanyan sòlda nan fanmi sa a ki t'ap viv lavil Jazè nan zòn Galarad. Chèf fanmi Ebwon an te rele Jerija.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 26, verseNumber = 32, text = "Nan fanmi an, te gen antou demilsètsan (2700) vanyan gason ki te chèf fanmi yo. Wa David te mete yo reskonsab branch fanmi Woubenn lan, branch fanmi Gad la ak mwatye nan branch fanmi Manase a ki t'ap viv lòt bò larivyè Jouden sou bò solèy leve, pou wè si tout bagay ki gen rapò ak sèvis Bondye ansanm ak zafè wa a t'ap mache byen.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 1, text = "Men lis chèf fanmi pèp Izrayèl la ak kòmandan rejiman mil sòlda ak kòmandan divizyon san sòlda ansanm ak lòt anplwaye yo te konte ki t'ap sèvi ak wa a nan gouvènman li. Chak mwa nan lanne a te gen yon gwoup vennkatmil gason (24.000) ki te desèvis sou lòd yon chèf diferan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 2, text = "Pou gwoup ki te desèvis pou premye mwa a, se Jachobeam, pitit gason Zabdyèl la, ki te chèf.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 3, text = "Se te yon moun nan fanmi Farèz. Li te kòmandan tout chèf lame ki te desèvis pou premye mwa a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 4, text = "Pou gwoup dezyèm mwa a, se te Dodayi, moun lavil Akoa, ki te chèf. Li te gen Miklòt pou adjwen.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 5, text = "Pou gwoup twazyèm mwa a, chèf lame a te rele Benaja, pitit Jeoyada, granprèt la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 6, text = "Benaja sa a te chèf trant pi vanyan sòlda yo. Apre li, se Amizabad, pitit gason l', ki te pran kòmandman gwoup la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 7, text = "Pou gwoup katriyèm mwa a, se Azayèl, frè Joab la, ki te chèf. Apre li, se Zebadya, pitit li, ki te pran kòmandman an.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 8, text = "Pou gwoup senkyèm mwa a, se Chamout, moun fanmi Izra, ki te chèf.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 9, text = "Pou gwoup sizyèm mwa a, se Ira, pitit gason Ikèch, moun lavil Tekoa, ki te chèf.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 10, text = "Pou gwoup setyèm mwa a, se Elèz, moun fanmi Efrayim nan lavil Pelon, ki te chèf.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 11, text = "Pou gwoup wityèm mwa a, se Sibekayi, moun lavil Oucha, ki te chèf. Se yon moun fanmi Zera nan gwo branch fanmi Jida a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 12, text = "Pou gwoup nevyèm mwa a, se Abyezè, moun lavil Anatòt nan branch fanmi Benjamen, ki te chèf.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 13, text = "Pou gwoup dizyèm mwa a, se Marayi, moun lavil Netofa nan fanmi Zera, ki te chèf.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 14, text = "Pou gwoup onzyèm mwa a, se Benaja, moun lavil Piraton nan zòn ki pou branch fanmi Efrayim lan, ki te chèf.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 15, text = "Pou gwoup douzyèm mwa a, se Eldayi, moun fanmi Otnyèl nan lavil Netofa, ki te chèf.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 16, text = "Men non chèf ki te reskonsab douz gwo branch fanmi pèp Izrayèl la: Pou branch fanmi Woubenn lan, se te Elyezè, pitit gason Zikri. Pou branch fanmi Simeyon an, se te Sefatya, pitit gason Maka.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 17, text = "Pou branch fanmi Levi a, se te Asabya, pitit gason Kemwèl. Pou branch fanmi Arawon an, se te Zadòk.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 18, text = "Pou branch fanmi Jida a, se te Eliyou, yonn nan frè David yo. Pou branch fanmi Isaka a, se te Omri, pitit gason Mikayèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 19, text = "Pou branch fanmi Zabilon an, se te Ismaja, pitit gason Obadya. Pou branch fanmi Neftali a, se te Jerimòt, pitit gason Azriyèl.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 20, text = "Pou branch fanmi Efrayim lan, se te Oze, pitit gason Azazya. Pou mwatye branch fanmi Manase a, se te Joèl, pitit gason Pedaja.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 21, text = "Pou lòt mwatye branch fanmi Manase a, ki te rete nan peyi Galarad, se te Ido, pitit gason Zakari. Pou branch fanmi Benjamen an, se te Jasiyèl, pitit gason Abnè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 22, text = "Pou branch fanmi Dann lan, se te Azareyèl, pitit gason Jeworam lan. Se yo ki te chèf branch fanmi pèp Izrayèl yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 23, text = "David pa t' fè konte moun ki pa t' ankò gen ventan sou tèt yo, paske Seyè a te pwomèt li t'ap fè pèp Izrayèl la peple pou yo te rive menm kantite ak zetwal nan syèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 24, text = "Joab, pitit gason Sewouya a, te konmanse ap konte moun nan pèp la, men li pa t' fin fè l' paske sa te lakòz Bondye te fache sou pèp la. Se konsa yo pa mete nan liv Istwa wa David la kantite moun yo te jwenn.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 25, text = "Se Azmavèt, pitit gason Adiyèl la, ki te reskonsab trezò wa a. Se Jonatan, pitit Ozyas la, ki te reskonsab tout depo ki te nan jaden, nan lavil, nan ti bouk ak sou fwontyè yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 26, text = "Se Ezri, pitit gason Keloub la, ki te reskonsab tout moun ki t'ap okipe jaden wa a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 27, text = "Se Chimeyi, moun lavil Rama, ki te reskonsab tout jaden rezen yo. Se Zabdi, moun lavil Chefam ki te reskonsab tout depo diven yo te fè ak rezen yo te ranmase nan jaden yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 28, text = "Se Baal anan, moun lavil Gedè, ki te reskonsab tout pye oliv ak pye sikomò ki te nan basrak yo. Se Joach ki te reskonsab depo lwil yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 29, text = "Se Chitrayi, moun Sawon, ki te reskonsab tout bèf yo t'ap gade nan zòn Sawon an. Se Chafat, pitit gason Adlayi, ki te reskonsab bèf yo t'ap gade nan fon yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 30, text = "Se Obil, moun fanmi Izmayèl yo, ki te reskonsab chamo yo. Se Jekdeja, moun lavil Mewonòt, ki te reskonsab fenmèl bourik yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 31, text = "Se Jazis, moun peyi Aga, ki te reskonsab mouton ak kabrit yo. Se tout moun sa yo ki te jeran tout byen wa David yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 32, text = "Jonatan, tonton David, te yon konseye. Se te yon moun lespri ki te fò anpil. Jekiyèl, pitit Akmoni, te reskonsab levasyon tout pitit gason wa a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 33, text = "Akitofèl te konseye wa a tou. Ouzayi, moun peyi Ak, te bon zanmi wa a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 27, verseNumber = 34, text = "Lè Akitofèl mouri, se Abyata ak Jeojada, pitit Benaja, ki vin konseye wa a. Joab te kòmandan lame wa a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 1, text = "David mande pou tout otorite peyi Izrayèl la reyini lavil Jerizalèm. Se konsa tout chèf branch fanmi yo, tout chèf gwoup ki te reskonsab dirije peyi a pou wa a, tout kòmandan rejiman mil sòlda yo ak kòmandan divizyon san sòlda yo, jeran tout tè ak gadò tout bèt ki pou wa a ak pou pitit li yo, moun konfyans li yo, chèf lame li yo ak tout vanyan sòlda li yo, yo tout reyini lavil Jerizalèm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 2, text = "David kanpe devan yo tout, li di yo konsa: -Frè m' yo ak nou tout moun nan pèp mwen an, koute sa m'ap di nou. Mwen te fè lide bati yon kay kote pou Bwat Kontra Seyè a rete, yon kay kote Seyè a ka mete fotèy li. Mwen te pare tout bagay pou bati kay la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 3, text = "Men, Bondye te fè m' konnen mwen p'ap ka bati kay la pou li paske se sòlda mwen ye, mwen fè twòp san koule.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 4, text = "Men se mwen menm Seyè a, Bondye Izrayèl la, te chwazi nan mitan tout fanmi m' yo pou fè m' wa peyi Izrayèl la pou tout tan. Li te chwazi branch fanmi Jida a pou pran kòmandman peyi a. Nan branch fanmi Jida a, li chwazi fanmi papa m'. Nan fanmi papa m', sa te fè l' plezi pou l' chwazi m' pou l' mete m' wa sou tout peyi Izrayèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 5, text = "Koulye a, Seyè a te ban mwen anpil pitit. Men, nan tout pitit sa yo li chwazi Salomon pou chita sou fotèy la pou gouvènen pèp Izrayèl la ak pouvwa l'ap ba li.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 6, text = "Seyè a te di m' tou: Se Salomon, pitit gason ou lan, ki va bati kay mwen an ak tout lakou yo. Se li menm mwen chwazi pou pitit mwen. M'a yon papa pou li.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 7, text = "M'ap fè gouvènman l' lan kanpe fèm pou tout tan, depi li menm li toujou kenbe lòd mwen, depi li toujou mache dapre kòmandman m' yo jan l'ap fè l' jòdi a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 8, text = "Koulye a, devan tout pèp Izrayèl la, pèp Bondye a ki sanble isit la, ak devan Bondye nou k'ap koute nou an, mwen mande pou nou kenbe tout kòmandman Seyè a, Bondye nou an, ban nou pou bèl peyi nou sa a toujou rete pou nou. Konsa, nou ka kite l' pou pitit nou yo jouk sa kaba.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 9, text = "Ou menm, Salomon, pitit mwen, se pou ou rekonèt Bondye papa ou la. Se pou ou sèvi l' ak tout kè ou, avèk bon santiman, paske Seyè a sonde kè tout moun, li konnen tou sa k'ap pase nan tèt yo. Konsa, si ou chache l', l'ap kite ou jwenn li. Men, si ou vire do ba li, l'ap lage ou nèt tou pou tout tan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 10, text = "Se pou ou rekonèt se Seyè a menm ki chwazi ou pou bati yon kay pou mete apa pou li. Mete gason sou ou! Antre nan travay!", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 11, text = "Apre sa, David bay Salomon plan tout kay tanp lan, plan tout chanm ak tout depo yo, plan tout lòt chanm sou anwo yo, chanm anndan yo ak plan gwo chanm yo mete apa pou Bondye a, kote yo fè sèvis pou mande padon pou peche yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 12, text = "Li ba li plan tout bagay li te gen nan tèt li pou lakou tanp yo, pou tout chanm ki bay sou lakou yo, pou depo veso yo sèvi nan tanp lan ak pou depo bagay yo ofri pou mete apa pou Seyè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 13, text = "David te ba li tou jan pou li òganize prèt yo ak moun Levi yo pou yo fè travay yo, jan pou yo fè tout sèvis nan kay Seyè a, ak jan pou yo okipe tout veso Tanp lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 14, text = "Li di li konbe ajan ak lò la bezwen pou fè veso yo,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 15, text = "pou chak lanp, pou chak gwo lanp sèt branch an ajan osinon an lò ak pèz yo chak dwe genyen dapre sèvis yo,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 16, text = "pou chak tab an ajan osinon an lò kote pou yo ranje pen yo mete apa pou Seyè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 17, text = "Li di li konbe lò l'a bezwen pou fè fouchèt yo, bòl yo, gwo gode yo, ak modèl lòt veso an ajan osinon an lò dapre pèz yo chak.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 18, text = "Li di l' konbe bon lò l'ap bezwen pou fè lotèl lansan an, ak lò pou fè kabwa a, pou pòtre zanj cheriben yo ak zèl yo louvri sou Bwat Kontra Seyè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 19, text = "David di li: -Tout plan travay la ekri an detay nan yon liv dapre lòd Seyè a menm te ban mwen. Li esplike m' tou sa pou m' fè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 20, text = "Apre sa, wa David di Salomon, pitit li a: -Mete gason sou ou! Pran kouraj, pitit mwen! Fè sa ou gen pou fè a! Pa kite anyen fè ou pè, paske Seyè a, Bondye mwen an, kanpe la avè ou, jouk tout travay pou sèvis Tanp lan fini.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 28, verseNumber = 21, text = "Gwoup prèt yo ak gwoup moun Levi yo deja resevwa travay pou yo fè nan Tanp lan. Pou tout lòt travay yo, ou gen avè ou ouvriye ki vle ede ou, lèfini ki gen ladrès nan tout kalite djòb. Chèf yo ak tout pèp la ap tann lòd ou pou tout bagay fèt.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 1, text = "Lèfini, David pale ak tout moun ki te sanble la yo, li di yo konsa: -Salomon, pitit gason m' lan, se li menm Bondye chwazi, men li jenn anpil, li pa gen esperyans. Travay la anpil, paske se pa yon kay pou moun li pral bati, men yon tanp pou Bondye, Seyè a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 2, text = "Mwen fè sa m' te kapab pou m' te pare materyo pou tanp lan: lò, ajan, kwiv, fè, bwa, bèl pyè oniks, bèl pyè pou sèvi ganiti, pyè malachit ak tout kalite lòt koulè, tout kalite bèl pyè koute chè ak mab an kantite.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 3, text = "Men, pou mete sou tou sa mwen pare pou kay n'ap mete apa pou Seyè a, mwen pran lò ak ajan mwen te genyen, mwen bay tout paske mwen renmen kay Bondye a anpil:", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 4, text = "sanmil (100.000) kilo bon lò ki soti nan peyi Ofi, ak desantrant (230) kilo bon ajan pou dekore miray Tanp lan,", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 5, text = "pou fè tout bèl bagay an lò osinon an ajan bòs atizan yo gen pou fè. Koulye a, kilès ankò ki vle bay ak tout kè li pou Bondye?", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 6, text = "Lè sa a, chèf branch fanmi yo, chèf chak fanmi pèp Izrayèl la, tout chèf rejiman mil sòlda yo ak chèf divizyon san sòlda yo, ak tout jeran ki t'ap travay pou wa a, fè kado yo te vle fè.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 7, text = "Yo bay sanswasannsenk (165) kilo lò, twasantrantmil (330.000) kilo ajan, sètsanmil (700.000) kilo kwiv konsa, ak twa milyon twasanmil (3,300.000) kilo fè pou travay Tanp lan.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 8, text = "Sa ki te gen bèl pyè koute chè bay yo pou trezò Tanp lan ki te sou kont Jeyèl, yon moun Levi nan fanmi Gèchon an.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 9, text = "Pèp la menm te kontan bay sa yo t'ap bay pou Seyè a paske yo te fè l' ak tout kè yo. Wa David tou te kontan anpil.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 10, text = "Lè sa a, David fè lwanj Bondye devan tout pèp la ki te reyini. Li di konsa: -Lwanj pou ou, Seyè a, Bondye Izrayèl, papa nou, depi tout tan ak pou tout tan!", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 11, text = "Seyè, ou gen pouvwa, ou gen kouraj! Se pou ou tout lwanj. W'ap donminen sou tout bagay pou tout tan. Tou sa ki nan syèl la ak sou latè a se pou ou yo ye. Se ou menm Seyè ki sel wa, paske ou sèl chèf sou tout bagay.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 12, text = "Se nan men ou tout richès ak tout byen soti. Ou gouvènen tout bagay avèk fòs ponyèt ou ak pouvwa ou. Se ou menm ki bay tout moun pouvwa ak fòs.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 13, text = "Koulye a, Bondye nou, nou di ou mèsi. N'ap fè lwanj pou ou sitèlman ou gen pouvwa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 14, text = "Men, kisa m' ye, kisa pèp mwen an ye menm, pou m' ta kapab ofri ou tout bagay sa yo ak tout kè nou? Se nan men ou tout bagay sa yo soti, se nan sa nou resevwa nan men ou n'ap ba ou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 15, text = "Seyè, ou konnen, devan ou se pase n'ap pase tankou moun k'ap vizite, menm jan ak tout zansèt nou yo. Lavi nou sou latè tankou yon nwaj k'ap pase. Wè pa wè fòk nou mouri.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 16, text = "Seyè, Bondye nou, nou pare tout richès sa yo pou bati yon kay pou ou, ou menm ki yon Bondye apa. Men, se nan men ou yo tout yo soti, se pou ou yo tout ye.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 17, text = "Mwen konnen, Bondye mwen, ou sonde kè tout moun, ou kontan ak moun ki mache dwat. Se poutèt sa, ak tout kè mwen, mwen ofri ou tout bagay sa yo. Koulye a mwen wè jan pèp ou a ki sanble isit la, kontan pou yo pote ofrann pa yo pou ou tou ak tout kè yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 18, text = "Seyè, Mèt, Bondye Abraram, Bondye Izarak ak Bondye Izrayèl, Bondye zansèt nou yo, tanpri, fè pèp ou a pa janm pèdi bon santiman sa yo ki nan kè yo jòdi a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 19, text = "Tanpri, bay Salomon, pitit gason m' lan, bon santiman tou pou li renmen ou nèt ale, pou li ka mache dapre lòd, regleman ak kòmandman ou yo nan tou sa l'ap fè, pou l' ka bati Tanp lan avèk tout materio mwen fin pare yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 20, text = "Apre sa David pale ankò ak tout pèp la ki te reyini, li di yo: -Annou fè lwanj pou Seyè a, Bondye nou an! Tout pèp la nèt pran fè lwanj Seyè a, Bondye zansèt yo. Yo mete jenou yo atè, yo bese tèt yo byen ba devan Seyè a ak devan wa a.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 21, text = "Nan denmen, yo ofri bèt pou yo touye pou Seyè a, yo boule kèk bèt nèt pou Seyè a: antou mil (1.000) ti towo bèf, mil (1.000) belye mouton, mil (1.000) jenn ti mouton ak ofrann diven ki fèt pou mache ak yo. Yo touye yon pakèt lòt bèt yo tè ofri bay Bondye pou pèp Izrayèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 22, text = "Jou sa a, yo manje, yo bwè ak gwo kè kontan dèvan Seyè a. Apre sa yon dezyèm fwa, yo fè deklarasyon yo rekonèt Salomon, pitit David la, pou wa yo. Yo fè sèvis mete l' apa pou l' chèf yo nan non Seyè a. Menm lè a, yo mete Zadòk apa pou l' sèvi granprèt nan non Seyè a tou.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 23, text = "Se konsa Salomon pran plas David, papa l', sou fotèy gouvènman Seyè a te tabli a. Tout zafè l' te mache byen. Tout pèp Izrayèl la te obeyi l'.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 24, text = "Tout chèf yo, tout sòlda yo ansanm ak tout lòt pitit David yo te rekonèt Salomon pou sèl chèf yo.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 25, text = "Seyè a te bay Salomon yon bèl pozisyon devan pèp la. Li te fè gouvènman Salomon an kanpe fèm ak yon pouvwa ankenn lòt wa nan peyi Izrayèl la pa t' janm genyen anvan sa.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 26, text = "David, pitit gason Izayi a, te gouvènen tout peyi Izrayèl la.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 27, text = "Li pase karantan ap gouvènen pèp Izrayèl la. Pandan sètan li te rete lavil Ebwon. Pandan rès tranntwazan yo, li te rete lavil Jerizalèm.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 28, text = "Lè li mouri, li te granmoun anpil, men kè li te kontan. Li te gen anpil richès. Tout moun t'ap fè lwanj pou li. Se Salomon, pitit gason l' lan, ki moute wa nan plas li.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 29, text = "Se nan liv istwa pwofèt Samyèl, liv istwa pwofèt Natan ak liv istwa pwofèt Gad nou jwenn istwa tou sa David te fè depi nan konmansman jouk li mouri.", bookId = 13),
        Verse(book = "1 Kwonik", chapter = 29, verseNumber = 30, text = "Liv sa yo fè nou konnen jan li te gouvènen, jan li te yon vanyan gason, ansanm ak tou sa ki te rive l', tou sa ki pase nan peyi Izrayèl la ak nan lòt peyi yo tou.", bookId = 13)
    )
}

